export type InputScheme = 'keyboard' | 'touch' | 'gamepad';
const labels: Record<Exclude<InputScheme,'keyboard'>, {leap:string; wait:string; zoom:string}> = {
    touch: {leap:'Jump + ', wait:'Wait: tap Wait', zoom:'Zoom: + / -'},
    gamepad: {leap:'Button1 + ', wait:'Wait: Button2', zoom:'Zoom: left/right trigger'},
};
export function formatInputHint(message: string, scheme: InputScheme): string {
    if (scheme === 'keyboard') return message;
    const label = labels[scheme];
    return message.replace(/Shift\+/g,label.leap)
        .replace(/Wait: Z\nor Period\/Space/g,label.wait)
        .replace(/Zoom view: \[ or \]|Zoom view with \[ and \]/g,label.zoom);
}
