import type { LevelSpec } from '../run/state';
import type { Adjacency,Room } from '../world/room-graph';

export type GenerationStage = 'specification' | 'layout' | 'topology' | 'analysis' | 'roles' | 'construction' | 'patrols' | 'population' | 'finalization' | 'validation';
export type RoomGraph = { readonly rooms: readonly Room[]; readonly adjacencies: readonly Adjacency[] };
export class GenerationError extends Error {
    constructor(readonly spec: LevelSpec, readonly stage: GenerationStage, readonly cause: unknown) {
        super(`Generation failed: seed=${JSON.stringify(spec.seed)} difficulty=${spec.difficulty} rules=${spec.rulesVersion} generator=${spec.generatorVersion} stage=${stage}: ${String(cause)}`);
        this.name = 'GenerationError';
    }
}
export class GenerationContext {
    private stage: GenerationStage = 'specification';
    constructor(readonly spec: LevelSpec) {}
    enter(stage: GenerationStage) { this.stage = stage; }
    failure(cause: unknown) { return new GenerationError(this.spec, this.stage, cause); }
}
