import type { Clock } from '../application/ports';
import { systemClock } from '../application/ports';
import { cloneData } from '../core/clone-data';
import type { PersistedStats,ProfileState,ScoreEntry } from '../profile/state';
import type { SimulationState } from '../simulation/state';
import type { AchievementEvent,Achievements,AchievementState as Facts } from './achievements';
import { getCurrentDateFormatted } from './date';
import { completedLevelBreakdown,incompleteLevelScore } from './scoring';
import type { RunState } from './state';

type ResultState = Pick<RunState, 'completedLevels' | 'gameMapRoughPlans' | 'level' | 'gameStats' | 'totalTurns' | 'dailyRun'> &
    Pick<SimulationState, 'gameMap' | 'mansion' | 'levelStats' | 'turns' | 'lootStolen'>;
type AchievementState = Facts & Pick<RunState, 'achievements'>;

function applyLevelResult(state: ResultState, score: number, completed: boolean, ghosted: boolean, clock: Clock) {
    state.completedLevels.add(state.level);
    const { gameStats, levelStats } = state;
    gameStats.totalScore += score;
    gameStats.turns = state.totalTurns;
    gameStats.numLevels = state.gameMapRoughPlans.length;
    gameStats.numCompletedLevels = state.level + (completed ? 1 : 0);
    if (completed && ghosted) ++gameStats.numGhostedLevels;
    gameStats.numInjuries += levelStats.damageTaken;
    gameStats.numKnockouts += levelStats.numKnockouts;
    gameStats.numSpottings += levelStats.numSpottings;
    gameStats.daily = state.dailyRun;
    gameStats.timeEnded = clock.now();
}

export function scoreCompletedLevel(state: ResultState, clock: Clock = systemClock) {
    if (state.completedLevels.has(state.level)) return;
    const { score, ghosted } = completedLevelBreakdown(state);
    applyLevelResult(state, score, true, ghosted, clock);
}

function scoreIncompleteLevel(state: ResultState, clock: Clock = systemClock) {
    if (state.completedLevels.has(state.level)) return;
    applyLevelResult(state, incompleteLevelScore(state), false, false, clock);
}

export function updateAchievements(state: AchievementState, type: AchievementEvent) {
    let key:keyof Achievements;
    for(key in state.achievements) {
        state.achievements[key].update(state, type);
    }
}

function persistAchievements(state: RunState & ProfileState) {
    let key:keyof Achievements;
    let pKey:keyof PersistedStats;
    for(key in state.achievements) {
        if(key in state.persistedStats) {
            pKey = key;
            if(!state.achievements[key].failed) {
                state.persistedStats[pKey]++;
                state.profile.writeStat(pKey, state.persistedStats[pKey]);
            }
        }
    }
}

export function recordWin(state: RunState & SimulationState & ProfileState, clock: Clock = systemClock) {
    if (state.resultRecorded) return;
    state.resultRecorded = 'won';
    state.persistedStats.totalWins++;
    const score = state.gameStats.totalScore;
    state.persistedStats.bestScore = Math.max(state.persistedStats.bestScore, score);
    const scoreEntry: ScoreEntry = {
        runId: state.runId,
        score: score,
        date: getCurrentDateFormatted(new Date(clock.now())),
        turns: state.totalTurns,
        level: state.level+1
    };
    updateAchievements(state, "gameEnd");
    state.persistedStats.scores.push(scoreEntry);
    if(state.dailyRun) {
        const daily = dailySummary(state);
        daily.bestScore = Math.max(daily.bestScore, score);
        daily.wins++;
        daily.winFirstTry = daily.plays === 1 ? 1 : daily.winFirstTry;
        if (state.persistedStats.currentDailyGameId === state.dailyRun) {
        state.persistedStats.currentDailyBestScore = daily.bestScore;
        state.persistedStats.currentDailyWins++;
        state.persistedStats.currentDailyWinFirstTry = state.persistedStats.currentDailyPlays===1?1:state.persistedStats.currentDailyWinFirstTry;
        }
        state.persistedStats.lastPlayedDailyGame = cloneData(state.gameStats);
        state.persistedStats.allDailyWins++;
        state.persistedStats.allDailyWinsFirstTry += daily.plays === 1 ? 1 : 0;
    }
    state.profile.writeStats(state.persistedStats);
    if (!state.dailyRun) {
        persistAchievements(state);
    }

}

export function recordDeath(state: ResultState & ProfileState & Pick<RunState, 'runId' | 'resultRecorded'>, clock: Clock = systemClock) {
    if (state.resultRecorded) return;
    state.resultRecorded = 'dead';
    scoreIncompleteLevel(state, clock);
    state.persistedStats.bestScore = Math.max(state.persistedStats.bestScore, state.gameStats.totalScore);
    const scoreEntry: ScoreEntry = {
        runId: state.runId,
        score: state.gameStats.totalScore,
        date: getCurrentDateFormatted(new Date(clock.now())),
        turns: state.totalTurns,
        level: state.level+1
    };
    state.persistedStats.scores.push(scoreEntry);
    if(state.dailyRun) {
        const daily = dailySummary(state);
        daily.bestScore = Math.max(daily.bestScore, state.gameStats.totalScore);
        if (state.persistedStats.currentDailyGameId === state.dailyRun) state.persistedStats.currentDailyBestScore = daily.bestScore;
        state.persistedStats.lastPlayedDailyGame = cloneData(state.gameStats);
    }
    state.profile.writeStats(state.persistedStats);
}

export function rolloverDailyProfile(state: ProfileState, clock: Clock = systemClock) {
    const stats = state.persistedStats;
    if (stats.currentDailyGameId === getCurrentDateFormatted(new Date(clock.now()))) return;
    stats.currentDailyGameId = getCurrentDateFormatted(new Date(clock.now()));
    const daily = stats.dailyHistory[stats.currentDailyGameId] ?? {plays:0,wins:0,bestScore:0,winFirstTry:0};
    stats.currentDailyPlays = daily.plays;
    stats.currentDailyWins = daily.wins;
    stats.currentDailyWinFirstTry = daily.winFirstTry;
    stats.currentDailyBestScore = daily.bestScore;
    state.profile.writeStats(stats);
}


export function dailySummary(state: Pick<RunState, 'dailyRun'> & ProfileState) {
    const date = state.dailyRun!;
    return state.persistedStats.dailyHistory[date] ??= {
        plays: state.persistedStats.currentDailyGameId === date ? state.persistedStats.currentDailyPlays : 0,
        wins: state.persistedStats.currentDailyGameId === date ? state.persistedStats.currentDailyWins : 0,
        bestScore: state.persistedStats.currentDailyGameId === date ? state.persistedStats.currentDailyBestScore : 0,
        winFirstTry: state.persistedStats.currentDailyGameId === date ? state.persistedStats.currentDailyWinFirstTry : 0,
    };
}
