import type { vec2 } from '../my-matrix';
import type { Cell,GameMap } from './game-map';
import { isWindowTerrainType } from './tiles';

export function lineOfSight(map: GameMap, from: vec2, to: vec2): boolean {
    let x = from[0];
    let y = from[1];

    const dx = to[0] - x;
    const dy = to[1] - y;

    let ax = Math.abs(dx);
    let ay = Math.abs(dy);

    const x_inc = (dx > 0) ? 1 : -1;
    const y_inc = (dy > 0) ? 1 : -1;

    let error = ay - ax;

    const nStart = ax + ay - 1;
    let n = nStart;

    ax *= 2;
    ay *= 2;

    while (n > 0) {
        if (error > 0) {
            y += y_inc;
            error -= ax;
        } else {
            if (error === 0) {
                const cell = map.cells.at(x, y + y_inc);
                if (cell.blocksSight) {
                    return false;
                }
                if (cell.isWindow && n > 1 && n < nStart - 1) {
                    return false;
                }
            }
            x += x_inc;
            error += ay;
        }

        const cell = map.cells.at(x, y);
        if (cell.blocksSight) {
            return false;
        }
        if (cell.isWindow && n > 1 && n < nStart - 1) {
            return false;
        }

        --n;
    }

    return true;
}

function blocksLineOfSightToCell(cell: Cell): boolean {
    if (cell.blocksSight) {
        return true;
    }

    if (isWindowTerrainType(cell.type)) {
        return true;
    }

    return false;
}

export function lineOfSightToPosition(map: GameMap, from: vec2, to: vec2): boolean {
    let x = from[0];
    let y = from[1];

    const dx = to[0] - x;
    const dy = to[1] - y;

    let ax = Math.abs(dx);
    let ay = Math.abs(dy);

    const x_inc = (dx > 0) ? 1 : -1;
    const y_inc = (dy > 0) ? 1 : -1;

    let error = ay - ax;

    let n = ax + ay - 1;

    ax *= 2;
    ay *= 2;

    while (n > 0) {
        if (error > 0) {
            y += y_inc;
            error -= ax;
        } else {
            if (error === 0 && blocksLineOfSightToCell(map.cells.at(x, y + y_inc))) {
                return false;
            }
            x += x_inc;
            error += ay;
        }

        const cell = map.cells.at(x, y);

        if (cell.blocksSight) {
            return false;
        }

        if (isWindowTerrainType(cell.type)) {
            return false;
        }

        --n;
    }

    return true;
}
