import type { KeyMap } from './bindings';
import { defaultKeyMap } from './bindings';
import { Controller } from './controller';
import { PhysicalKeyboard } from './physical-keyboard';
export class KeyboardController extends Controller {
    private readonly physical: PhysicalKeyboard;
    constructor(readonly keyMap: KeyMap = defaultKeyMap) {
        super();
        this.physical = new PhysicalKeyboard(keyMap);
        this.listen(document, 'keydown', (event: KeyboardEvent) => this.keyDownHandler(event));
        this.listen(document, 'keyup', (event: KeyboardEvent) => this.keyUpHandler(event));
    }
    clearPressedAll() { super.clearPressedAll(); this.physical?.clear(); }
    private reconcile(event: KeyboardEvent, down: boolean) {
        if (event.target instanceof HTMLElement && ['INPUT', 'TEXTAREA', 'BUTTON'].includes(event.target.tagName)) return;
        const actions = this.physical.update(event.code, down, event.altKey, event.ctrlKey);
        for (const action of new Set([...Object.keys(this.controlStates), ...actions])) {
            const pressed = actions.has(action);
            if (!!this.controlStates[action] !== pressed) this.setPressed(action, pressed);
        }
        if (actions.size) event.preventDefault();
    }
    keyDownHandler(event: KeyboardEvent) { this.reconcile(event, true); }
    keyUpHandler(event: KeyboardEvent) { this.reconcile(event, false); }
}
