import type { vec2 } from '../my-matrix';

export enum RoomType {
    Exterior,
    PublicCourtyard,
    PublicRoom,
    PrivateCourtyard,
    PrivateRoom,
    Vault,
    Bedroom,
    Dining,
    PublicLibrary,
    PrivateLibrary,
    Kitchen,
    Treasure,
    TreasureCourtyard,
    LockedTreasure,
    LockedTreasureCourtyard,
    ThroneRoom,
}

export enum DoorType {
    Standard,
    GateFront,
    GateBack,
    Locked,
}

export type Room = {
    roomType: RoomType,
    group: number,
    depth: number,
    privateRoom: boolean,
    posMin: vec2,
    posMax: vec2,
    edges: Array<Adjacency>,
    gridX: number,
    gridY: number,
}

export type Adjacency = {
    origin: vec2,
    dir: vec2,
    length: number,
    roomLeft: Room,
    roomRight: Room,
    nextMatching: Adjacency | null,
    door: boolean,
    doorType: DoorType,
}

export function numDoorsInWall(room: Room, dx: number, dy: number): number {
    let n = 0;
    for (const adj of room.edges) {
        if (!adj.door) {
            continue;
        }
        let dxWall = -adj.dir[1];
        let dyWall = adj.dir[0];
        if (adj.roomLeft === room) {
            dxWall = -dxWall;
            dyWall = -dyWall;
        }
        if (dxWall === dx && dyWall === dy) {
            ++n;
        }
    }
    return n;
}
