const resources: Readonly<Record<string,string>> = {
    createTexture:'deleteTexture', createBuffer:'deleteBuffer', createVertexArray:'deleteVertexArray',
    createProgram:'deleteProgram', createShader:'deleteShader',
};
export function ownGL(context: WebGL2RenderingContext) {
    const owned = new Map<string, Set<object>>();
    const gl = new Proxy(context, {get(target, key) {
        const value = Reflect.get(target,key,target);
        if (typeof value !== 'function') return value;
        return (...args: unknown[]) => {
            const name = String(key), result = value.apply(target,args);
            if (resources[name] && result === null) throw new Error('Graphics resources could not be allocated.');
            if (resources[name] && result) {
                const entries = owned.get(resources[name]) ?? new Set(); entries.add(result); owned.set(resources[name],entries);
            } else if (name.startsWith('delete')) owned.get(name)?.delete(args[0] as object);
            return result;
        };
    }});
    return {gl, dispose() {
        for (const [method, entries] of owned) for (const object of entries)
            (context[method as keyof WebGL2RenderingContext] as (value:object)=>void).call(context,object);
        owned.clear();
    }};
}
