import type { GameMap } from '../world/game-map';
import type { GuardData } from '../world/guard';
import { GuardMode } from '../world/guard-mode';

const schedules = new WeakMap<GameMap, GuardData[]>();
export function guardSchedule(map: GameMap, reorder = false): GuardData[] {
    const previous = schedules.get(map) ?? map.guards;
    const present = new Set(map.guards);
    const ordered = previous.filter(guard => present.has(guard));
    for (const guard of map.guards) if (!ordered.includes(guard)) ordered.push(guard);
    if (reorder) ordered.sort((a,b) =>
        Number(b.mode === GuardMode.ChaseVisibleTarget) - Number(a.mode === GuardMode.ChaseVisibleTarget) ||
        b.patrolPath.length - a.patrolPath.length);
    schedules.set(map, ordered);
    return ordered;
}
