import { invariant } from '../core/invariant';
import type { LevelSpec } from '../run/state';
import type { GameMap } from '../world/game-map';
import { ItemType } from '../world/tiles';
import type { RoomGraph } from './stages';

export function validateRoomGraph({rooms, adjacencies}: RoomGraph) {
    const roomSet = new Set(rooms), edgeSet = new Set(adjacencies);
    for (const edge of adjacencies) {
        invariant(roomSet.has(edge.roomLeft) && roomSet.has(edge.roomRight), 'Edge has an unknown room');
        invariant(edge.roomLeft !== edge.roomRight, 'Self edge');
        invariant(edge.roomLeft.edges.includes(edge) && edge.roomRight.edges.includes(edge), 'Nonreciprocal edge');
        invariant(edge.length > 0 && Number.isInteger(edge.length), 'Invalid edge length');
        let cursor = edge.nextMatching, remaining = adjacencies.length + 1;
        while (cursor && cursor !== edge && remaining-- > 0) {
            invariant(edgeSet.has(cursor), 'Matching edge outside graph'); cursor = cursor.nextMatching;
        }
        invariant(remaining > 0, 'Unbounded matching chain');
    }
    for (const room of rooms) for (const edge of room.edges)
        invariant(edgeSet.has(edge) && (edge.roomLeft === room || edge.roomRight === room), 'Invalid room edge ownership');
}

export function validateFinalMap(map: GameMap, spec: LevelSpec) {
    const valid = (p: ArrayLike<number>) => map.cells.contains(p[0], p[1]);
    invariant(valid(map.playerStartPos) && !map.cells.atVec(map.playerStartPos).blocksPlayerMove, 'Invalid player start');
    invariant(map.items.filter(i => i.type === ItemType.Coin).length + map.guards.filter(g => g.hasPurse).length === spec.totalLoot, 'Required loot total mismatch');
    for (const item of map.items) invariant(valid(item.pos), 'Item outside map');
    for (const guard of map.guards) {
        invariant(guard.patrolPath.length > 0 && valid(guard.pos), 'Invalid guard spawn');
        for (let i = 0; i < guard.patrolPath.length; i++) {
            const a = guard.patrolPath[i], b = guard.patrolPath[(i+1)%guard.patrolPath.length];
            invariant(valid(a) && Math.abs(a[0]-b[0]) <= 1 && Math.abs(a[1]-b[1]) <= 1, 'Discontinuous patrol');
            invariant(Number.isFinite(map.guardMoveCost(a,b)), 'Patrol crosses blocked terrain or a corner');
        }
    }
    for (const treasure of map.treasures) for (const pos of treasure.switches)
        invariant(map.items.some(i => i.type === ItemType.Bookshelf && i.pos.equals(pos)), 'Switch has no bookshelf');
}
