import { vec2 } from '../my-matrix';

export const cardinalDirections: Array<vec2> = [
    vec2.fromValues(-1, 0),
    vec2.fromValues(1, 0),
    vec2.fromValues(0, -1),
    vec2.fromValues(0, 1),
];

export type PortalInfo = {
    // offset of left corner of portal relative to lower-left corner of cell:
    lx: number;
    ly: number;
    // offset of right corner of portal relative to lower-left-corner of cell:
    rx: number;
    ry: number;
    // offset of neighboring cell relative to this cell's coordinates:
    nx: number;
    ny: number;
}

export const portals: Array<PortalInfo> = [
    { lx: -1, ly: -1, rx: -1, ry:  1, nx: -1, ny:  0 },
    { lx: -1, ly:  1, rx:  1, ry:  1, nx:  0, ny:  1 },
    { lx:  1, ly:  1, rx:  1, ry: -1, nx:  1, ny:  0 },
    { lx:  1, ly: -1, rx: -1, ry: -1, nx:  0, ny: -1 },
];

export const lightPortals: Array<PortalInfo> = [
    { lx: -1, ly: -1, rx: -1, ry: -1, nx: -1, ny: -1 },
    { lx: -1, ly: -1, rx: -1, ry:  1, nx: -1, ny:  0 },
    { lx: -1, ly:  1, rx: -1, ry:  1, nx: -1, ny:  1 },
    { lx: -1, ly:  1, rx:  1, ry:  1, nx:  0, ny:  1 },
    { lx:  1, ly:  1, rx:  1, ry:  1, nx:  1, ny:  1 },
    { lx:  1, ly:  1, rx:  1, ry: -1, nx:  1, ny:  0 },
    { lx:  1, ly: -1, rx:  1, ry: -1, nx:  1, ny: -1 },
    { lx:  1, ly: -1, rx: -1, ry: -1, nx:  0, ny: -1 },
];

export function aRightOfB(ax: number, ay: number, bx: number, by: number): boolean {
    return ax * by > ay * bx;
}

export type AdjacentMove = {
    dx: number;
    dy: number;
    cost: number;
}

export const adjacentMoves: Array<AdjacentMove> = [
    { dx:  1, dy:  0, cost: 2 },
    { dx: -1, dy:  0, cost: 2 },
    { dx:  0, dy:  1, cost: 2 },
    { dx:  0, dy: -1, cost: 2 },
    { dx: -1, dy: -1, cost: 3 },
    { dx:  1, dy: -1, cost: 3 },
    { dx: -1, dy:  1, cost: 3 },
    { dx:  1, dy:  1, cost: 3 },
];

export type DistPos = {
    priority: number; // = distance; needs to be named priority for PriorityQueueElement
    pos: vec2;
}
