import type { GameMap,Player } from './game-map';

export class WorldIdentity {
    private ids = new WeakMap<object, string>();
    private objects = new Map<string, object>();
    private next = 0;
    constructor(readonly levelId: string) {}
    identify(object: object): string {
        let id = this.ids.get(object);
        if (!id) {
            id = this.levelId + '/' + (++this.next);
            this.ids.set(object, id);
            this.objects.set(id, object);
        }
        return id;
    }
    resolve(id: string): object | undefined { return this.objects.get(id); }
    register(map: GameMap, player: Player) {
        for (const object of [player, ...map.items, ...map.guards]) this.identify(object);
    }
}
