export type ControlStates = { [id:string]: boolean};
type ControlTimes = { [id:string]: number};

const controlStates0: ControlStates = {
    'left': false,
    'right': false,
    'up': false,
    'down': false,
    'wait': false,
    'jump': false,
    'zoomIn': false,
    'zoomOut': false,
    'snapToPlayer': false,
    'menuAccept': false,
    'panUp': false,
    'panDown': false,
    'panLeft': false,
    'panRight': false,
    'menu': false,
    'menuBack': false,
    'menuToggle': false,
    'homePlay': false,
    'homeMultiFloor': false,
    'homeDaily': false,
    'homeStats': false,
    'homeAchievements': false,
    'homeOptions': false,
    'jumpToggle': false,
    'startLevel': false,
    'guardMute': false,
    'volumeMute': false,
    'volumeDown': false,
    'volumeUp': false,
    'forceRestart': false,
    'resetState': false,
    'seeAll': false,
    'collectLoot': false,
    'getKey': false,
    'markSeen': false,
    'guardSight': false,
    'guardPatrols': false,
    'roomAdjacencies': false,
    'nextLevel': false,
    'prevLevel': false,
    'fullscreen': false,
    'showSpeech': false,
    'idleCursorToggle': false,
    'showFPS':false,
    'devMenu':false,
};

export let lastController:Controller|null = null;

export class Controller {
    controlStates: ControlStates;
    controlTimes: ControlTimes;
    currentFramePresses: Set<string> = new Set();
    protected readonly lifetime = new AbortController();
    protected listen<T extends Event>(target: EventTarget, type: string, handler: (event: T) => void, capture = false) {
        target.addEventListener(type, handler as EventListener, {capture, signal: this.lifetime.signal});
    }
    dispose() { this.clearPressedAll(); this.lifetime.abort(); if (lastController === this) lastController = null; }
    constructor() {
        this.controlStates = {... controlStates0};
        this.controlTimes = {};
        for(const c in this.controlStates) {
            this.controlTimes[c] = Date.now();
        }
        this.listen(window, 'blur', _e=>{
            this.clearPressedAll();
        });
    }
    setPressed(action:string, state:boolean, updateFrame:boolean=true) {
        this.controlStates[action] = state;
        this.controlTimes[action] = Date.now();
        if(updateFrame) {
            if(state) {
                this.currentFramePresses.add(action);
            }
        }
        lastController = this;
    }
    clearPressedAll() {
        for(const c in this.controlStates) {
            this.controlStates[c] = false;
            this.controlTimes[c] = 0;
        }
        this.currentFramePresses.clear();
    }
    endFrame() {
        this.currentFramePresses.clear();
    }
}


export function activateController(controller: Controller) { lastController = controller; }
