import { isClimbableItem,isDoorItemType,isPlinthTreasure,isWallTerrainType,isWindowTerrainType,ItemType,TerrainType } from './tiles';




// TODO: Figure out how to make a generic grid data structure

enum LevelType {
    Manor,
    ManorRed,
    Mansion,
    Fortress,
    Warrens,
}

function levelTypeName(levelType: LevelType): string {
    switch (levelType) {
        case LevelType.Manor: return 'Manor';
        case LevelType.ManorRed: return 'Manor';
        case LevelType.Mansion: return 'Mansion';
        case LevelType.Fortress: return 'Fortress';
        case LevelType.Warrens: return 'Warrens';
    }
}

enum GuardStates {
    Relaxed,
    Angry,
    Alerted,
    Chasing,
    Unconscious,
}

type Item = {
    pos: vec2;
    type: ItemType;

}

function guardMoveCostForItemType(itemType: ItemType): number {
    switch (itemType) {
        case ItemType.Chair: return 32;
        case ItemType.Table: return 64;
        case ItemType.BedL: return 64;
        case ItemType.BedR: return 64;
        case ItemType.DrawersShort: return Infinity;
        case ItemType.DrawersTall: return Infinity;
        case ItemType.Bookshelf: return Infinity;
        case ItemType.Shelf: return Infinity;
        case ItemType.Stove: return Infinity;
        case ItemType.Bush: return 10;
        case ItemType.Coin: return 0;
        case ItemType.Health: return 0;
        case ItemType.DoorNS: return 0;
        case ItemType.DoorEW: return 0;
        case ItemType.LockedDoorNS: return 0;
        case ItemType.LockedDoorEW: return 0;
        case ItemType.PortcullisNS: return 0;
        case ItemType.PortcullisEW: return 0;
        case ItemType.TorchUnlit: return Infinity;
        case ItemType.TorchLit: return Infinity;
        case ItemType.TorchCarry: return 0;
        case ItemType.PurseCarry: return 0;
        case ItemType.Key: return 0;
        case ItemType.KeyCarry: return 0;
        case ItemType.Note: return 0;
        case ItemType.TreasureLock: return Infinity;
        case ItemType.TreasurePlinth: return Infinity;
        case ItemType.VaultTreasureBox: return Infinity;
        case ItemType.EmptyVaultTreasureBox: return Infinity;
        case ItemType.LootedVaultTreasureBox: return Infinity;
        case ItemType.TreasureA: return Infinity;
        case ItemType.TreasureB: return Infinity;
        case ItemType.TreasureC: return Infinity;
        case ItemType.TreasureD: return Infinity;
        case ItemType.TreasureE: return Infinity;
    }
}

const maxPlayerHealth: number = 5;
const maxPlayerHealthDaily: number = 3;
const maxPlayerTurnsUnderwater: number = 7;

class Player {
    pos: vec2;
    dir: vec2;
    health: number;
    healthMax: number;
    loot: number;
    noisy: boolean; // did the player make noise last turn?
    preNoisy: boolean; // did the player step at wall last turn?
    noiseOffset: vec2; // which direction was the noise made relative to the player's position?
    hasVaultKey: boolean;
    damagedLastTurn: boolean;
    itemUsed: Item | null = null; // item player used last turn, if any
    turnsRemainingUnderwater: number;
    interactionTarget: {kind:'guard'; guard:Guard} | {kind:'bookshelf'; item:Item} | null = null;
    lightActive: boolean = false;
    elevated = false;

    constructor(pos: vec2, dailyRun: boolean) {
        this.pos = vec2.clone(pos);
        this.dir = vec2.fromValues(0, -1);
        this.healthMax = dailyRun ? maxPlayerHealthDaily : maxPlayerHealth;
        this.health = this.healthMax;
        this.loot = 0;
        this.noisy = false;
        this.preNoisy = false;
        this.noiseOffset = vec2.fromValues(0, 0);
        this.hasVaultKey = false;
        this.damagedLastTurn = false;
        this.turnsRemainingUnderwater = maxPlayerTurnsUnderwater;
    }

    applyDamage(d: number) {
        this.health -= Math.min(d, this.health);
        this.damagedLastTurn = true;
    }

    hidden(map: GameMap): boolean {
        if (this.lightActive || this.elevated) {
            return false;
        }

        if (map.guards.find((guard) => guard.mode == GuardMode.ChaseVisibleTarget) !== undefined) {
            return false;
        }

        if (map.cells.atVec(this.pos).hidesPlayer) {
            return true;
        }

        let cellType = map.cells.atVec(this.pos).type;

        if (cellType == TerrainType.GroundWater && this.turnsRemainingUnderwater > 0) {
            return true;
        }

        return false;
    }
}

type Rect = {
    posMin: vec2;
    posMax: vec2;
}















type TreasureInfo = {
    switches: Array<vec2>;
    numSwitchesUsed: number;
    posTreasure: vec2;
    stolen: boolean;
}

class GameMap {
    private lightSlots = new WeakMap<object, number>();
    lightSlot(source: object): number {
        let slot = this.lightSlots.get(source);
        if (slot === undefined) {
            slot = this.lightCount++;
            this.lightSlots.set(source, slot);
        }
        return slot;
    }

    readonly stairs: Stair[] = [];
    readonly openings = new Set<number>();
    readonly platforms = new Set<number>();
    hasElevation = false;

    isOpening(pos: vec2): boolean {
        return this.cells.contains(pos[0], pos[1]) && this.openings.has(this.cells.indexVec(pos));
    }

    hasHighSurface(pos: vec2): boolean {
        if (!this.hasElevation || !this.cells.contains(pos[0], pos[1]) ||
            isWallTerrainType(this.cells.atVec(pos).type)) return false;
        return this.platforms.has(this.cells.indexVec(pos)) ||
            this.items.some(item => item.pos.equals(pos) && isClimbableItem(item.type));
    }
    allowsEscape = true;
    exitPositions?: readonly vec2[];

    canEscapeFrom(pos: vec2): boolean {
        return this.allowsEscape && (this.exitPositions?.some(exit => exit.equals(pos)) ?? true);
    }

    isLadderSpace(pos: vec2): boolean {
        return this.stairs.some(stair => stair.pos.equals(pos) || stair.arrival?.equals(pos));
    }

    stairAt(pos: vec2): Stair | undefined {
        return this.stairs.find(stair => stair.pos.equals(pos));
    }

    cells: CellGrid;
    patrolRegions: Array<Rect>;
    patrolRoutes: Array<[number, number]>;
    items: Array<Item>;
    guards: Array<Guard>;
    playerStartPos: vec2;
    lightCount: number;
    numPreRevealedCells: number;
    backtrackingCoefficient: number;
    bookTitle: Map<Item, string>;
    treasures: Array<TreasureInfo>;

    // Development visualization data:
    rooms: Array<Rect>;
    adjacencies: Array<Adjacency>;

    constructor(cells: CellGrid) {
        this.cells = cells;
        this.patrolRegions = [];
        this.patrolRoutes = [];
        this.items = [];
        this.guards = [];
        this.playerStartPos = vec2.create();
        this.lightCount = 0;
        this.numPreRevealedCells = 0;
        this.backtrackingCoefficient = 1;
        this.bookTitle = new Map();
        this.treasures = [];

        this.rooms = [];
        this.adjacencies = [];
    }

    hasLootAt(pos: vec2): boolean {
        return this.items.some(item =>
            item.pos.equals(pos) && (
                item.type === ItemType.Coin ||
                isPlinthTreasure(item.type) ||
                item.type === ItemType.Health ||
                item.type === ItemType.VaultTreasureBox
            ));
    }

    collectLootAt(pos:vec2): Array<Item> {
        let items:Array<Item> = [];
        const lockedTreasure = this.items.some(item => item.type === ItemType.TreasureLock && item.pos.equals(pos));
        this.items = this.items.filter((item) => {
            if (!item.pos.equals(pos)) {
                return true;
            } else if (item.type === ItemType.Coin || item.type === ItemType.Health) {
                items.push(item);
                return false;
            } else if (isPlinthTreasure(item.type) && !lockedTreasure) {
                items.push(item);
                return false;
            } else if (item.type === ItemType.VaultTreasureBox) {
                items.push(item);
                return false;
            } else {
                return true;
            }
        });
        return items;
    }

    collectAllLoot(): number {
        let gold = 0;
        this.items = this.items.filter((item) => {
            if (item.type != ItemType.Coin) {
                return true;
            } else {
                ++gold;
                return false;
            }
        });
        for(let g of this.guards) {
            if(g.hasPurse) {
                ++gold;
                g.hasPurse = false;
            }
        }
        return gold;
    }

    identifyAdjacentCells(pos: vec2) {
        const xMin = Math.max(pos[0] - 1, 0);
        const yMin = Math.max(pos[1] - 1, 0);
        const xMax = Math.min(pos[0] + 2, this.cells.sizeX);
        const yMax = Math.min(pos[1] + 2, this.cells.sizeY);

        for (let x = xMin; x < xMax; ++x) {
            for (let y = yMin; y < yMax; ++y) {
                this.cells.at(x, y).identified = true;
            }
        }
    }

    allSeen(): boolean {
        const {values} = this.cells;
        for (let index = 0; index < values.length; index++) {
            if (!values[index].seen && !this.openings.has(index)) return false;
        }
        return true;
    }

    numCells(): number {
        return this.cells.values.length - this.openings.size;
    }

    numCellsSeen(): number {
        let numSeen = 0;
        const {values} = this.cells;
        for (let index = 0; index < values.length; index++) {
            if (values[index].seen && !this.openings.has(index)) ++numSeen;
        }
        return numSeen;
    }

    fractionRevealed(): number {
        const total = this.numCells() - this.numPreRevealedCells;
        return total <= 0 ? 1 : (this.numCellsSeen() - this.numPreRevealedCells) / total;
    }

    markAllSeen() {
        for (const cell of this.cells.values) {
            cell.seen = true;
            cell.identified = true;
        }
    }

    markAllUnseen() {
        for (const cell of this.cells.values) {
            cell.seen = false;
            cell.identified = false;
        }
    }

    recomputeVisibility(posViewer: vec2): void { return visibility.recomputeVisibility.call(this, posViewer); }

    recomputeVisibilityFromPos(posViewer: vec2): void { return visibility.recomputeVisibilityFromPos.call(this, posViewer); }

    playerCanSeeInDirection(posViewer: vec2, dir: vec2): boolean { return visibility.playerCanSeeInDirection.call(this, posViewer, dir); }

    computeVisibility(viewerX: number, viewerY: number, targetX: number, targetY: number, ldx: number, ldy: number, rdx: number, rdy: number): void { return visibility.computeVisibility.call(this, viewerX, viewerY, targetX, targetY, ldx, ldy, rdx, rdy); }

    computeLighting(player: Player | null): void { return lighting.computeLighting.call(this, player); }

    castLight(posLight: vec2, radiusSquared: number, lightId:number, occupied:Set<Cell>): void { return lighting.castLight.call(this, posLight, radiusSquared, lightId, occupied); }

    castLightRecursive(lightX: number, lightY: number, targetX: number, targetY: number, ldx: number, ldy: number, rdx: number, rdy: number, radiusSquared: number, lightId: number, occupied:Set<Cell>): void { return lighting.castLightRecursive.call(this, lightX, lightY, targetX, targetY, ldx, ldy, rdx, rdy, radiusSquared, lightId, occupied); }

    isGuardAt(x: number, y: number): boolean { return navigation.isGuardAt.call(this, x, y); }

    isGuardAtVec(pos: vec2): boolean { return navigation.isGuardAtVec.call(this, pos); }

    guardMoveCost(posOld: vec2, posNew: vec2): number { return navigation.guardMoveCost.call(this, posOld, posNew); }

    posNextBest(distanceField: Float64Grid, posFrom: vec2): vec2 { return navigation.posNextBest.call(this, distanceField, posFrom); }

    nextPositions(distanceField: Float64Grid, posFrom: vec2): vec2[] { return navigation.nextPositions.call(this, distanceField, posFrom); }

    patrolPathIndexForResume(patrolPositions: Array<vec2>, patrolIndexCur: number, pos: vec2): number { return navigation.patrolPathIndexForResume.call(this, patrolPositions, patrolIndexCur, pos); }

    computeDistancesToPosition(posGoal: vec2, queryRect: Rect | undefined): Float64Grid { return navigation.computeDistancesToPosition.call(this, posGoal, queryRect); }

    computeDistancesToPositionSubrect(posGoal: vec2, xMin: number, yMin: number, xMax: number, yMax: number): Float64Grid { return navigation.computeDistancesToPositionSubrect.call(this, posGoal, xMin, yMin, xMax, yMax); }

    computeDistancesToAdjacentToPosition(posGoal: vec2, queryRect: Rect): Float64Grid { return navigation.computeDistancesToAdjacentToPosition.call(this, posGoal, queryRect); }

    computeDistanceField(initialDistances: Array<DistPos>, queryRect: Rect | undefined): Float64Grid { return navigation.computeDistanceField.call(this, initialDistances, queryRect); }

    numNavigableSquaresInRect(rect: Rect): number { return navigation.numNavigableSquaresInRect.call(this, rect); }

    computeDistanceFieldSubrect(initialDistances: Array<DistPos>, xMin: number, yMin: number, xMax: number, yMax: number): Float64Grid { return navigation.computeDistanceFieldSubrect.call(this, initialDistances, xMin, yMin, xMax, yMax); }

    guardsInEarshot(soundPos: vec2, costCutoff: number): GuardData[] { return acoustics.guardsInEarshot.call(this, soundPos, costCutoff); }

    tryGetPosLookAt(pos: vec2, includeDoors: boolean): vec2 | undefined { return spatial.tryGetPosLookAt.call(this, pos, includeDoors); }
}
