import { itemPalette, levelThemes, terrainAt, terrainPalette, type LevelFile, type LevelFloor, type TilePosition } from '../application/levels/format';
import { spriteSheets, spritesPerSheetSide, type TileInfo } from '../tilesets';
import { FloorId } from '../world/mansion';
import { connectsWallTile, TerrainType } from '../world/tiles';
import { entityTileSet, itemTileSetForLevelType, terrainTileSet, terrainTileSetForLevelType } from './tiles';

const tileSize = 28;

export function pointerTile(canvas: HTMLCanvasElement, event: PointerEvent): TilePosition {
    const {left, top, width, height} = canvas.getBoundingClientRect();
    const x = Math.floor((event.clientX - left) * canvas.width / width / tileSize);
    const row = Math.floor((event.clientY - top) * canvas.height / height / tileSize);
    return [x, canvas.height / tileSize - 1 - row];
}

export function drawLevelPreview(canvas: HTMLCanvasElement, level: LevelFile, floor: LevelFloor, cursor: TilePosition, guard: number) {
    const width = floor.terrain[0].length;
    const height = floor.terrain.length;
    if (canvas.width !== width * tileSize) canvas.width = width * tileSize;
    if (canvas.height !== height * tileSize) canvas.height = height * tileSize;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.imageSmoothingEnabled = false;
    ctx.fillStyle = '#1c1924';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    const theme = levelThemes[level.theme].type;
    const terrainTiles = terrainTileSetForLevelType(theme, terrainTileSet);
    const itemTiles = itemTileSetForLevelType(theme, entityTileSet);
    const screenY = (y: number) => (height - y - 1) * tileSize;

    function sprite(tile: TileInfo, [x, y]: TilePosition) {
        if (tile.textureIndex === undefined) return;
        const {image} = spriteSheets[tile.atlas];
        if (!image.naturalWidth) return;
        const sx = image.naturalWidth / spritesPerSheetSide;
        const sy = image.naturalHeight / spritesPerSheetSide;
        const col = tile.textureIndex % spritesPerSheetSide;
        const row = Math.floor(tile.textureIndex / spritesPerSheetSide);
        ctx!.drawImage(image, col * sx, row * sy, sx, sy, x * tileSize, screenY(y), tileSize, tileSize);
    }
    function label(text: string, [x, y]: TilePosition, color: string) {
        ctx!.font = 'bold 15px system-ui';
        ctx!.textAlign = 'center';
        ctx!.textBaseline = 'middle';
        ctx!.fillStyle = '#18141f';
        ctx!.fillRect(x * tileSize + 3, screenY(y) + 3, tileSize - 6, tileSize - 6);
        ctx!.fillStyle = color;
        ctx!.fillText(text, (x + .5) * tileSize, screenY(y) + tileSize / 2);
    }

    const terrainType = (x: number, y: number) => x >= 0 && x < width && y >= 0 && y < height
        ? terrainPalette[terrainAt(floor, [x, y])].type : TerrainType.GroundNormal;
    for (let y = 0; y < height; y++) {
        for (let x = 0; x < width; x++) {
            const code = terrainAt(floor, [x, y]);
            const tile = terrainPalette[code];
            let type: TerrainType = tile.type;
            if (type === TerrainType.Wall0000) {
                type += (connectsWallTile(terrainType(x, y + 1)) ? 8 : 0) + (connectsWallTile(terrainType(x, y - 1)) ? 4 : 0) +
                    (connectsWallTile(terrainType(x + 1, y)) ? 2 : 0) + (connectsWallTile(terrainType(x - 1, y)) ? 1 : 0);
            }
            if (code === 'o') {
                ctx.fillStyle = '#141e31';
                ctx.fillRect(x * tileSize, screenY(y), tileSize, tileSize);
            } else {
                sprite(terrainTiles[type], [x, y]);
            }
            if ('fixture' in tile) sprite(itemTiles[tile.fixture], [x, y]);
            ctx.strokeStyle = '#211b2b66';
            ctx.strokeRect(x * tileSize + .5, screenY(y) + .5, tileSize, tileSize);
        }
    }
    for (const item of floor.items) sprite(itemTiles[itemPalette[item.type].type], item.at);
    const patrol = floor.guards[guard]?.patrol;
    if (patrol?.length) {
        ctx.strokeStyle = '#ffbe75';
        ctx.lineWidth = 2;
        ctx.beginPath();
        for (const [x, y] of patrol) ctx.lineTo((x + .5) * tileSize, screenY(y) + tileSize / 2);
        ctx.stroke();
    }
    for (const [index, item] of floor.guards.entries()) {
        label(String(index + 1), item.patrol[0], index === guard ? '#ffbe75' : '#fdb4d0');
    }
    for (const at of floor.platforms ?? []) label('=', at, '#aad7ec');
    for (const stair of floor.stairs) label(stair.to > floor.id ? '↑' : '↓', stair.at, '#9eeaff');
    if (floor.id === FloorId.First) {
        for (const exit of level.exits) label('↗', exit, '#9de6a5');
        label('P', level.start, '#e8dcff');
    }
    ctx.strokeStyle = '#e5c3ff';
    ctx.lineWidth = 2;
    ctx.strokeRect(cursor[0] * tileSize + 1, screenY(cursor[1]) + 1, tileSize - 2, tileSize - 2);
}
