import { vec2 } from '../my-matrix';
import type { FloorId,Mansion } from './mansion';
import { lineOfSight } from './sight';

export function clearVerticalSight(mansion: Mansion, from: FloorId, fromPos: vec2, to: FloorId, toPos: vec2, raisedTarget: boolean): boolean {
    if (from === to) {
        const floor = mansion.floors.find(floor => floor.id === from);
        return !!floor && lineOfSight(floor.map, fromPos, toPos);
    }

    // Intersect the sight ray with each story's floor at that story's height.
    const fromZ = from * 2 + 0.5;
    const toZ = to * 2 + (raisedTarget ? 1.5 : 0.5);
    const direction = Math.sign(to - from);
    let pos = fromPos;
    for (let id = Number(from); id !== to; id += direction) {
        const floor = mansion.floors.find(floor => floor.id === id);
        const upper = mansion.floors.find(floor => floor.id === id + (direction > 0 ? 1 : 0));
        const height = (id + (direction > 0 ? 1 : 0)) * 2;
        const t = (height - fromZ) / (toZ - fromZ);
        const x = Math.floor(fromPos[0] + 0.5 + t * (toPos[0] - fromPos[0]));
        const y = Math.floor(fromPos[1] + 0.5 + t * (toPos[1] - fromPos[1]));
        const crossing = vec2.fromValues(x,y);
        if ((upper && !upper.map.isOpening(crossing)) ||
            (floor && !lineOfSight(floor.map, pos, crossing))) return false;
        pos = crossing;
    }
    const destination = mansion.floors.find(floor => floor.id === to);
    return !!destination && lineOfSight(destination.map, pos, toPos);
}
