import { cloneData } from '../core/clone-data';
import { defaultSettings,defaultStats } from './defaults';
import type { PersistedStats,ProfileSettings,ScoreEntry } from './state';

export type StoragePort = {
    getItem(key: string): string | null;
    setItem(key: string, value: string): void;
    removeItem(key: string): void;
};

const snapshotKey = 'LLL/profile/v1';
type Setting = keyof ProfileSettings;
type Snapshot = {
    version: 1;
    revision: number;
    settings: ProfileSettings;
    stats: PersistedStats;
    legacyBackup: Record<string, string>;
};

function record(value: unknown): value is Record<string, unknown> {
    return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function counter(value: unknown): value is number {
    return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
}

function score(value: unknown): value is ScoreEntry {
    return record(value) && counter(value.score) && counter(value.turns) &&
        counter(value.level) && typeof value.date === 'string' && /^\d{4}\/\d{2}\/\d{2}$/.test(value.date);
}

function settingsFrom(value: unknown): ProfileSettings {
    const result = { ...defaultSettings };
    if (!record(value)) return result;
    for (const name of Object.keys(result) as Setting[]) {
        const item = value[name];
        if (typeof result[name] === 'boolean') {
            if (typeof item === 'boolean') Object.assign(result, { [name]: item });
        } else if (typeof item === 'number' && Number.isFinite(item)) {
            const [min, max] = name === 'soundVolume' ? [0, 1] : [50, 2000];
            if (item >= min && item <= max) Object.assign(result, { [name]: item });
        }
    }
    return result;
}

function statsFrom(value: unknown): PersistedStats {
    const result = defaultStats();
    if (!record(value)) return result;
    for (const name of Object.keys(result) as (keyof PersistedStats)[]) {
        const item = value[name];
        if (name === 'dailyHistory') {
            if (record(item)) {
                for (const [date, summary] of Object.entries(item)) {
                    if (/^\d{4}\/\d{2}\/\d{2}$/.test(date) && record(summary) &&
                        ['plays','wins','bestScore','winFirstTry'].every(key => counter(summary[key]))) {
                        result.dailyHistory[date] = summary as PersistedStats['dailyHistory'][string];
                    }
                }
            }
        } else if (name === 'scores') {
            if (Array.isArray(item)) result.scores = item.filter(score);
        } else if (name === 'currentDailyGameId') {
            if (typeof item === 'string' && /^(?:\d{4}\/\d{2}\/\d{2})?$/.test(item)) result[name] = item;
        } else if (name === 'lastPlayedDailyGame') {
            if (record(item) && Object.entries(resultForValidation()).every(([key, initial]) =>
                typeof initial === 'number' ? counter(item[key]) :
                item[key] === null || typeof item[key] === 'string')) {
                result[name] = item as PersistedStats['lastPlayedDailyGame'];
            }
        } else if (counter(item)) result[name] = item;
    }
    return result;
}

function resultForValidation() {
    return {
        totalScore: 0, turns: 0, numLevels: 0, numCompletedLevels: 0, numGhostedLevels: 0,
        numSpottings: 0, numInjuries: 0, numKnockouts: 0, daily: null, timeStarted: 0, timeEnded: 0,
    };
}

export class ProfileStore {
    readonly diagnostics: string[] = [];
    persisted = true;
    private snapshot?: Snapshot;
    private saved: string | null = null;
    private unableToMigrate = false;

    constructor(private readonly storage: StoragePort) {}

    private read(key: string): string | null {
        try { return this.storage.getItem(key); }
        catch { this.unableToMigrate = true; this.persisted = false; this.diagnostics.push('Profile storage cannot be read'); return null; }
    }

    private parse(text: string | null): unknown {
        if (text === null || text === 'undefined') return undefined;
        try { return JSON.parse(text) as unknown; }
        catch { this.diagnostics.push('Invalid saved profile data'); return undefined; }
    }

    private load(): Snapshot {
        if (this.snapshot) return this.snapshot;
        this.saved = this.read(snapshotKey);
        const stored = this.parse(this.saved);
        if (record(stored) && stored.version === 1 && counter(stored.revision)) {
            this.snapshot = {
                version: 1, revision: stored.revision, settings: settingsFrom(stored.settings),
                stats: statsFrom(stored.stats), legacyBackup: record(stored.legacyBackup) ?
                    Object.fromEntries(Object.entries(stored.legacyBackup).filter((entry): entry is [string, string] =>
                        typeof entry[1] === 'string')) : {},
            };
            return this.snapshot;
        }
        if (record(stored) && stored.version !== undefined && stored.version !== 1) {
            this.unableToMigrate = true; this.persisted = false;
            this.diagnostics.push('Saved profile version is unsupported; existing data was preserved.');
        }
        const backup: Record<string, string> = {};
        if (this.saved !== null) backup[snapshotKey] = this.saved;
        const legacy: Record<string, unknown> = {};
        for (const name of [...Object.keys(defaultStats()), 'highScores']) {
            const key = 'LLL/stat/' + name;
            const raw = this.read(key);
            if (raw !== null) backup[key] = raw;
            legacy[name] = this.parse(raw);
        }
        if (!Array.isArray(legacy.scores)) legacy.scores = legacy.highScores;
        const settings: Record<string, unknown> = {};
        for (const name of Object.keys(defaultSettings)) {
            const key = 'LLL/' + name;
            const raw = this.read(key);
            if (raw !== null) backup[key] = raw;
            settings[name] = this.parse(raw);
        }
        this.snapshot = {
            version: 1, revision: 0, stats: statsFrom(legacy),
            settings: settingsFrom(settings), legacyBackup: backup,
        };
        this.save();
        return this.snapshot;
    }

    private save(): boolean {
        if (this.unableToMigrate) return this.persisted = false;
        const data = this.snapshot!;
        try {
            if (this.storage.getItem(snapshotKey) !== this.saved) {
                this.diagnostics.push('Another page changed the profile. Reload to resume saving.');
                return this.persisted = false;
            }
            const next = JSON.stringify({ ...data, revision: data.revision + 1 });
            this.storage.setItem(snapshotKey, next);
            data.revision++;
            this.saved = next;
            return this.persisted = true;
        } catch {
            this.diagnostics.push('Profile changes are available in this page but could not be saved.');
            return this.persisted = false;
        }
    }

    readSettings(): ProfileSettings { return { ...this.load().settings }; }
    readStats(): PersistedStats { return cloneData(this.load().stats); }

    writeSetting(name: Setting, value: string): boolean {
        this.load().settings = settingsFrom({ ...this.load().settings, [name]: this.parse(value) });
        return this.save();
    }

    writeStat<K extends keyof PersistedStats>(name: K, value: PersistedStats[K]): boolean {
        this.load().stats = statsFrom({ ...this.load().stats, [name]: value });
        return this.save();
    }

    writeStats(value: PersistedStats): boolean {
        this.load().stats = statsFrom(value);
        return this.save();
    }

    clear() {
        this.load();
        const owned = [
            snapshotKey,
            ...Object.keys(defaultStats()).map(name => 'LLL/stat/' + name), 'LLL/stat/highScores',
            ...Object.keys(defaultSettings).map(name => 'LLL/' + name),
        ];
        for (const key of new Set(owned)) {
            try { this.storage.removeItem(key); }
            catch { this.diagnostics.push('A profile key could not be removed'); }
        }
        this.unableToMigrate = false;
        this.saved = this.read(snapshotKey);
        this.snapshot = { version: 1, revision: 0, stats: defaultStats(), settings: { ...defaultSettings }, legacyBackup: {} };
        this.save();
    }
}
