import type { GeneratorVersion } from '../core/versions';
import { createGameMap,createGameMapRoughPlans } from '../generation';
import { RNG } from '../random';
import type { HeistState,LevelStats } from '../simulation/state';
import type { GameMap,LevelType } from '../world/game-map';
import { Player } from '../world/game-map';
import { getAchievements } from './achievements';
import type { GameStats,LevelSpec,RunState } from './state';

const gameConfig = { numGameMaps: 10, totalGameLoot: 100 };

export function normalPlans(rng: RNG, forceLevelType: LevelType | undefined, version?: GeneratorVersion) {
    return createGameMapRoughPlans(gameConfig.numGameMaps, gameConfig.totalGameLoot, rng, forceLevelType, version);
}

export function newRunStats(daily: string | null, timeStarted: number): GameStats {
    return {
        totalScore: 0,
        turns: 0,
        numLevels: 0,
        numCompletedLevels: 0,
        numGhostedLevels: 0,
        numSpottings: 0,
        numInjuries: 0,
        numKnockouts: 0,
        daily,
        timeStarted,
        timeEnded: 0,
    };
}

export function newLevelStats(): LevelStats {
    return { numKnockouts: 0, numSpottings: 0, damageTaken: 0, extraFoodCollected: 0, steppableLeaps: 0 };
}

export function configureInitialRun(level: number, forceLevelType: LevelType | undefined, seed?: string,
    generateMap = createGameMap, custom?: {spec: LevelSpec; map: GameMap}, version?: GeneratorVersion): HeistState & RunState {
    const rng = new RNG(seed);
    const plans = custom ? [custom.spec] : normalPlans(rng, forceLevelType, version);
    const map = custom?.map ?? generateMap(plans[level]);
    return {
        runId: rng.seed,
        resultRecorded: null,
        completedLevels: new Set(),
        rng,
        level,
        gameMapRoughPlans: plans,
        gameMap: map,
        player: new Player(map.playerStartPos, false),
        gameStats: newRunStats(null, 0),
        levelStats: newLevelStats(),
        achievements: getAchievements(),
        dailyRun: null,
        turns: 0,
        totalTurns: 0,
        lootStolen: 0,
        lootAvailable: plans[level].totalLoot,
        treasureStolen: 0,
        finishedLevel: false,
        hasEnteredMansion: false,
        numStepMoves: 0,
        numLeapMoves: 0,
        numWaitMoves: 0,
        experiencedPlayer: false,
        hasStartedGame: false,
    };
}
