import type { Controller } from '../controllers';
import { lastController } from '../controllers';
import type { Direction } from '../simulation/commands';
import { panDistance,zoomIn,zoomOut } from './camera';
import { setGuardMute,setSoundVolume,setVolumeMute } from './settings';
import type { State } from './state';
import { GameMode } from './state';

const lastFloorChangeDirection = new WeakMap<Controller, Direction>();

export function updateControllerState(state:State) {
    state.gamepadManager.updateGamepadStates();
    if(lastController !== null) {
        if (state.game.customTitle && state.levelEditor && (menuActivated('menu') || menuActivated('menuToggle'))) {
            state.levelEditor.returnFromPlaytest();
        } else if (state.gameMode === GameMode.Mansion) {
            onControlsInMansion(lastController);
        } else {
            state.textWindows[state.gameMode]?.onControls(state, menuActivated);
        }
        state.touchController.endFrame();
        state.keyboardController.endFrame();
        for(const g in state.gamepadManager.gamepads) state.gamepadManager.gamepads[g].endFrame();
    }
    function activated(action:string):boolean {
        const dt = Date.now();
        let result = false;
        if(lastController===null) return false;
        const controlStates = lastController.controlStates;
        if(!(action in controlStates)) return false;
        const threshold = state.keyRepeatActive===action? state.keyRepeatRate:state.keyRepeatDelay;
        result = lastController.currentFramePresses.has(action) ||
                 controlStates[action] &&
                 dt-lastController.controlTimes[action]>threshold;
        if(result) {
            if(controlStates[action] && dt-lastController.controlTimes[action]>threshold) {
                state.keyRepeatActive = action;
            }
            lastController.controlTimes[action] = dt;
        }
        if(!controlStates[action] && state.keyRepeatActive===action) state.keyRepeatActive = undefined;
        return result;
    }
    function menuActivated(action:string):boolean {
        //same as activated but no repeating, which is better for menus
        let result = false;
        if(lastController===null) return false;
        const controlStates = lastController.controlStates;
        if(!(action in controlStates)) return false;
        result = lastController.currentFramePresses.has(action);
        if(result) lastController.controlTimes[action] = Date.now();
        return result;
    }

    function onControlsInMansion(controller: Controller) {
        if (controller.controlStates['panLeft']) {
            state.camera.panning = true;
            state.camera.position[0] -= panDistance(state.camera.scale, state.frameElapsed);
        }
        if (controller.controlStates['panRight']) {
            state.camera.panning = true;
            state.camera.position[0] += panDistance(state.camera.scale, state.frameElapsed);
        }
        if (controller.controlStates['panUp']) {
            state.camera.panning = true;
            state.camera.position[1] += panDistance(state.camera.scale, state.frameElapsed);
        }
        if (controller.controlStates['panDown']) {
            state.camera.panning = true;
            state.camera.position[1] -= panDistance(state.camera.scale, state.frameElapsed);
        }
        if (controller.controlStates['snapToPlayer']) {
            state.camera.panning = false;
        }
        const movement = state.leapToggleActive !== controller.controlStates['jump'] ? 'leap' : 'step';
        function move(direction: Direction): boolean {
            if (lastFloorChangeDirection.get(controller) === direction && !controller.currentFramePresses.has(direction)) return false;
            if (!activated(direction)) return false;
            const result = state.session.execute({type: movement, direction});
            if (result.events.some(event => event.type === 'floor-changed')) lastFloorChangeDirection.set(controller, direction);
            else lastFloorChangeDirection.delete(controller);
            return true;
        }
        if (move('left') || move('right') || move('down') || move('up')) return;
        if (activated('wait')) {
            const {gameMap, player} = state.game;
            const onLadder = !player.elevated && gameMap.stairAt(player.pos);
            if (!onLadder || controller.currentFramePresses.has('wait')) {
                state.session.execute({ type: 'wait' });
            }
        } else if (activated('menu') || activated('menuToggle')) {
            state.session.openMenu();
        } else if (activated('jumpToggle')) {
            state.leapToggleActive = !state.leapToggleActive;
        } else if (activated('seeAll')) {
            if (state.devMode) {
                state.seeAll = !state.seeAll;
            }
        } else if (activated('collectLoot')) {
            if (state.devMode) state.session.collectDebugLoot();
        } else if (activated('getKey')) {
            if (state.devMode) state.session.grantDebugKey(false);
        } else if (activated('forceRestart')) {
            state.session.restartCurrentRun();
        } else if (activated('nextLevel')) {
            if (state.devMode) state.session.moveDebugLevel(1, true);
        } else if (activated('resetState')) {
            if (state.devMode) state.session.resetMansion();
        } else if (activated('prevLevel')) {
            if (state.devMode) state.session.moveDebugLevel(-1, true);
        } else if (activated('showFPS')) {
            if (state.devMode) {
                state.fpsInfo.enabled = !state.fpsInfo.enabled;
            }
        } else if (activated('guardSight')) {
            if (state.devMode) {
                state.seeGuardSight = !state.seeGuardSight;
            }
        } else if (activated('guardPatrols')) {
            if (state.devMode) {
                state.seeGuardPatrols = !state.seeGuardPatrols;
            }
        } else if (activated('roomAdjacencies')) {
            if (state.devMode) {
                state.seeRoomAdjacencies = !state.seeRoomAdjacencies;
            }
        } else if (activated('markSeen')) {
            if (state.devMode) state.session.revealDebugMap();
        } else if (activated('zoomIn')) {
            zoomIn(state);
        } else if (activated('zoomOut')) {
            zoomOut(state);
        } else if (activated('guardMute')) {
            setGuardMute(state, !state.guardMute);
            state.popups.setNotification('Guard speech: ' + (state.guardMute ? 'disabled' : 'enabled'), state.game.player, 3, 2.0);
        } else if (activated('idleCursorToggle')) {
            switch (state.visuals.player(state.game.player).idleCursorType) {
                case 'orbs':
                    state.visuals.player(state.game.player).idleCursorType = 'off';
                    break;
                case 'off':
                    state.visuals.player(state.game.player).idleCursorType = 'orbs';
                    break;
            }
            state.visuals.player(state.game.player).idle = false;
            state.idleTimer = 2;
            state.popups.setNotification("Player idle cursor: "+state.visuals.player(state.game.player).idleCursorType, state.game.player, 3, 2.0);
        } else if (activated('volumeMute')) {
            setVolumeMute(state, !state.volumeMute);
            state.popups.setNotification('Sound: ' + (state.volumeMute ? 'disabled' : 'enabled'), state.game.player, 3, 2.0);
        } else if (activated('volumeDown')) {
            const soundVolume = Math.max(0.1, state.soundVolume - 0.1);
            setSoundVolume(state, soundVolume);
            state.popups.setNotification('Sound volume: ' + Math.floor(state.soundVolume * 100 + 0.5) + '%', state.game.player, 3, 2.0);
        } else if (activated('volumeUp')) {
            const soundVolume = Math.min(1.0, state.soundVolume + 0.1);
            setSoundVolume(state, soundVolume);
            state.popups.setNotification('Sound volume: ' + Math.floor(state.soundVolume * 100 + 0.5) + '%', state.game.player, 3, 2.0);
        } else if (activated('showSpeech')) {
            state.popups.toggleShow(state.game.player.pos);
        }
    }
}
