import { vec2 } from '../my-matrix';
import type { GameMap } from './game-map';

export enum FloorId {
    Basement = -1,
    First = 0,
    Second = 1,
    Third = 2,
    Rooftop = 3,
}

export type Stair = {
    readonly pos: vec2;
    readonly destination: FloorId;
    arrival?: vec2;
};

export type MansionFloor = {
    readonly id: FloorId;
    readonly map: GameMap;
};

export type Mansion = {
    readonly floors: readonly MansionFloor[];
};

export function floorName(id: FloorId): string {
    switch (id) {
        case FloorId.Basement: return 'Basement';
        case FloorId.First: return 'First floor';
        case FloorId.Second: return 'Second floor';
        case FloorId.Third: return 'Third floor';
        case FloorId.Rooftop: return 'Rooftop';
    }
}

export type MansionView = { readonly gameMap: GameMap; readonly mansion?: Mansion };

export function mansionMaps(state: MansionView): readonly GameMap[] {
    return state.mansion?.floors.map(floor => floor.map) ?? [state.gameMap];
}

export function mansionRevealed(state: MansionView): number {
    let seen = 0;
    let total = 0;
    for (const map of mansionMaps(state)) {
        seen += map.numCellsSeen() - map.numPreRevealedCells;
        total += map.numCells() - map.numPreRevealedCells;
    }
    return total <= 0 ? 1 : seen / total;
}

const around = [[1,0],[0,1],[-1,0],[0,-1]] as const;

export function ladderArrivals(map: GameMap, stair: Stair): vec2[] {
    const [x,y] = stair.pos;
    return around.map(([dx,dy]) => vec2.fromValues(x + dx, y + dy))
        .filter(pos => map.cells.contains(pos[0], pos[1]) &&
            map.cells.atVec(pos).moveCost === 0 && !map.stairAt(pos) &&
            !map.items.some(item => item.pos.equals(pos)) &&
            !map.exitPositions?.some(exit => exit.equals(pos)));
}

export function assignLadderArrivals(map: GameMap): boolean {
    for (const stair of map.stairs) {
        const pos = ladderArrivals(map, stair).find(pos =>
            !map.guards.some(guard => guard.patrolPath.some(point => point.equals(pos))));
        if (!pos) return false;
        stair.arrival = pos;
    }
    for (const stair of map.stairs) {
        if (stair.arrival) map.cells.atVec(stair.arrival).moveCost = Infinity;
    }
    return true;
}

export function exposedFloorAt(mansion: Mansion, from: FloorId, pos: vec2, includeHighSurfaces = false): MansionFloor | undefined {
    for (let id = from; id >= FloorId.Basement; id--) {
        const floor = mansion.floors.find(floor => floor.id === id);
        if (!floor?.map.cells.contains(pos[0], pos[1])) continue;
        if (!floor.map.isOpening(pos) || (includeHighSurfaces && id < from && floor.map.hasHighSurface(pos))) {
            return id < from ? floor : undefined;
        }
    }
    return undefined;
}
