import { spriteAtlasIds, spriteSheetCapacity } from '../presentation/tile-types';
import type { SpriteAddress, TileInfo } from '../presentation/tile-types';

export function textScale(width: number, height: number, columns: number, rows: number, preferred: number): number {
    return Math.max(0.01, Math.min(preferred, width / Math.max(1, columns * 8 + 16), height / Math.max(1, rows * 16 + 16)));
}
export function* textGlyphs(lines: readonly string[]) {
    for (let i = 0; i < lines.length; i++) for (let col = 0; col < lines[i].length; col++) {
        const character = lines[i][col];
        if (character !== ' ') yield {row: lines.length - i - 1, col, glyphIndex: character.charCodeAt(0)};
    }
}

export function spriteTag(tile: TileInfo): string {
    return tile.textureIndex === undefined ? '' : `#${tile.atlas}:${tile.textureIndex}#`;
}

export function parseSpriteTag(tag: string): SpriteAddress | undefined {
    const match = /^(\d+):(\d+)$/.exec(tag);
    if (!match) return;
    const atlas = Number(match[1]);
    const textureIndex = Number(match[2]);
    return spriteAtlasIds.includes(atlas) && textureIndex < spriteSheetCapacity ? {atlas, textureIndex} : undefined;
}
