import type { Animator } from '../animation';
import type { GameReadModel } from '../application/session';
import type { ActiveHowlPool,Howls,SubtitledHowls } from '../audio';
import type { GamepadManager,KeyboardController,TouchController } from '../controllers';
import type { vec2 } from '../my-matrix';
import type { Popups } from '../popups';
import type { ProfileSettings,ProfileState } from '../profile/state';
import type { TurnFeedback } from '../simulation/feedback';
import type { TextWindow } from '../ui';
import type { GameSession } from './session';
import type { TimerScope } from './timers';
import type { WorldVisuals } from './visuals';

export { GameMode,AmbienceType };
export type { Camera,State };

type Camera = {
    position: vec2;
    velocity: vec2;
    joltOffset: vec2;
    joltVelocity: vec2;
    zoom: number;
    zoomVelocity: number;
    scale: number;
    anchor: vec2;
    snapped: boolean;
    zoomed: boolean;
    panning: boolean;
}

enum GameMode {
    HomeScreen,
    StatsScreen,
    AchievementsScreen,
    OptionsScreen,
    HelpControls,
    HelpKey,
    Mansion,
    MansionComplete,
    Dead,
    Win,
    DailyHub,
    CreditsScreen,
    DevScreen,
}

enum AmbienceType {
    Indoor,
    Outdoor,
    OutdoorWater,
    Water,
    Kitchen,
}

interface Particle {
    pos:vec2;
    animation?: Animator;
}

type HealthBarState = {
    damageDisplayTimer: number;
    healing: boolean;
    size: number;
    enlargeTimeRemaining: number;
    heartFlashRemaining: Array<number>;
}

type FPSInfo = {
    enabled: boolean;
    frames: number;
    cumulativeTime: number;
    worstFrame: number;
    drops: number;
    msgFPS: string;
}

export type BrowserState = {
    game: GameReadModel;
    feedback?: TurnFeedback;
    levelEditor?: {open(load?: boolean): void; isOpen(): boolean; returnFromPlaytest(): void};
    timers: TimerScope;
    session: GameSession;
    fpsInfo: FPSInfo;
    devMode: boolean;
    tLast: number | undefined;
    lightStates: Array<number>;
    dt: number;
    frameElapsed: number;
    idleTimer: number;
    keyRepeatActive: string|undefined;
    leapToggleActive: boolean;
    gameMode: GameMode;
    textWindows: {[key in GameMode]?: TextWindow };
    particles: Array<Particle>;
    visuals: WorldVisuals;
    oldPlayerPos: vec2,
    ambience: AmbienceType;
    ambientSoundPool: ActiveHowlPool;
    hintMessage: string;
    healthBarState: HealthBarState;
    numZoomMoves: number;
    zoomLevel: number;
    seeAll: boolean;
    seeGuardSight: boolean;
    seeGuardPatrols: boolean;
    seeRoomAdjacencies: boolean;
    camera: Camera;
    sounds: Howls;
    subtitledSounds: SubtitledHowls;
    activeSoundPool: ActiveHowlPool;
    touchController: TouchController;
    keyboardController: KeyboardController;
    gamepadManager: GamepadManager;
    popups: Popups;
}

type State = BrowserState & ProfileSettings & Pick<ProfileState, 'profile'>;
