import type { TweenData } from '../animation';
import { FrameAnimator,SpriteAnimation,tween } from '../animation';
import { vec2 } from '../my-matrix';
import type { TurnFeedback } from '../simulation/feedback';
import { GuardSpeech } from '../simulation/guard-speech';
import type { TileInfo } from '../tilesets';
import { playMoveSound } from './ambience';
import { joltCamera } from './camera';
import { enlargeHealthBar,flashHeart } from './health-bar';
import type { State } from './state';
import { entityTileSet,itemTileSetForLevelType } from './tiles';
import { showMoveTutorialNotifications } from './tutorials';

function animateBump(state: State, dx: number, dy: number) {
    const pos0 = vec2.create();
    const pos1 = vec2.fromValues(dx/4, dy/4);

    state.visuals.player(state.game.player).animation = new SpriteAnimation(
        [
            {pt0:pos0, pt1:pos1, duration:0.05, fn:tween.linear},
            {pt0:pos1, pt1:pos0, duration:0.05, fn:tween.linear}
        ],
        [entityTileSet.playerTiles.normal]);
}

function animateLoot(offset: vec2, height: number, tile: TileInfo, delayed: boolean): SpriteAnimation {
    const start = vec2.create();
    const middle = offset.scale(0.3333).add(vec2.fromValues(0, 0.5 + height / 2));
    const flight = [
        {pt0:start, pt1:middle, duration:0.1, fn:tween.easeOutQuad},
        {pt0:middle, pt1:offset, duration:0.1, fn:tween.easeInQuad},
    ];
    const tiles = [tile, tile];
    if (delayed) {
        flight.unshift({pt0:start, pt1:start, duration:0.1, fn:tween.easeOutQuad});
        tiles.unshift(tile);
    }
    const animation = new SpriteAnimation(flight, tiles);
    animation.removeOnFinish = true;
    return animation;
}

function soundNameForGuardSpeech(popupType: GuardSpeech): string {
    switch (popupType) {
        case GuardSpeech.Damage: return 'guardDamage';
        case GuardSpeech.GuardChase: return 'guardChase';
        case GuardSpeech.GuardSeeThief: return 'guardSeeThief';
        case GuardSpeech.GuardHearThief: return 'guardHearThief';
        case GuardSpeech.GuardHearGuard: return 'guardHearGuard';
        case GuardSpeech.GuardSpotDownedGuard: return 'guardSpotDownedGuard';
        case GuardSpeech.GuardSeeTorchLit: return 'guardSeeTorchLit';
        case GuardSpeech.GuardSeeUnlitTorch: return 'guardSeeUnlitTorch';
        case GuardSpeech.GuardDownWarning: return 'guardDownWarning';
        case GuardSpeech.GuardAwakesWarning: return 'guardAwakesWarning';
        case GuardSpeech.GuardWarningResponse: return 'guardWarningResponse';
        case GuardSpeech.GuardInvestigate: return 'guardInvestigate';
        case GuardSpeech.GuardEndChase: return 'guardEndChase';
        case GuardSpeech.GuardFinishInvestigating: return 'guardFinishInvestigating';
        case GuardSpeech.GuardFinishLooking: return 'guardFinishLooking';
        case GuardSpeech.GuardFinishListening: return 'guardFinishListening';
        case GuardSpeech.GuardFinishLightingTorch: return 'guardFinishLightingTorch';
        case GuardSpeech.GuardFinishLookingAtLitTorch: return 'guardFinishLookingAtLitTorch';
        case GuardSpeech.GuardStirring: return 'guardStirring';
        case GuardSpeech.GuardSeeTorchDoused: return 'guardSeeTorchDoused';
        case GuardSpeech.GuardSpotStolenTreasure: return 'guardSpotStolenTreasure';
        case GuardSpeech.GuardExamineStolenTreasure: return 'guardExamineStolenTreasure';
    }
}

export function createTurnFeedback(state: State): TurnFeedback {
    return {
        beginAction() {
            state.visuals.player(state.game.player).idle = false;
            state.idleTimer = 5;
            state.camera.panning = false;
            state.touchController.clearMotion();
        },
        advanceNotification: () => state.popups.updateNotification(),
        notify: (...args) => state.popups.setNotification(...args),
        holdNotification: (...args) => state.popups.setNotificationHold(...args),
        sound(name, volume, pan) {
            if (pan === undefined) state.sounds[name]?.play(volume);
            else state.sounds[name]?.play(volume, pan);
        },
        delaySound: (name, volume, ms) => { state.timers.schedule(() => state.sounds[name]?.play(volume), ms); },
        tutorial: previousPosition => showMoveTutorialNotifications(state, previousPosition),
        movementSound: (from, to) => playMoveSound(state, from, to),
        flashHeart: i => flashHeart(state, i),
        enlargeHealthBar: () => enlargeHealthBar(state),
        jolt: (dx, dy) => joltCamera(state, dx, dy),
        vaultGold(position, frameDuration) {
            const animation = new FrameAnimator(entityTileSet.vaultGoldAnimationTiles, frameDuration, 0, 1);
            animation.removeOnFinish = true;
            state.particles.push({ pos: position, animation });
        },
        bump: (dx, dy) => animateBump(state, dx, dy),
        fall(dx, dy, stories) {
            const {playerTiles} = entityTileSet;
            const facing = dx < 0 ? playerTiles.left : dx > 0 ? playerTiles.right : dy > 0 ? playerTiles.up : playerTiles.down;
            const tile = state.game.player.hidden(state.game.gameMap) ? playerTiles.hidden : facing;
            state.visuals.player(state.game.player).animation = new SpriteAnimation([
                {pt0: vec2.fromValues(-0.4 * dx, 0.65 * stories), pt1: vec2.create(), duration: 0.18 + 0.04 * stories, fn: tween.easeInQuad},
            ], [tile]);
        },
        lootFly(type, position, toward, offset, count) {
            const itemTiles = itemTileSetForLevelType(state.game.gameMapRoughPlans[state.game.level].levelType, entityTileSet);
            for (let i = 0; i < count; i++) {
                const animation = animateLoot(toward.subtract(position).add(vec2.fromValues(0, offset)),
                    offset, itemTiles[type], false);
                animation.time = -i * 0.2;
                state.particles.push({pos: vec2.clone(position), animation});
            }
        },
        guardLootFly(item, toward, delay) {
            const itemTiles = itemTileSetForLevelType(state.game.gameMapRoughPlans[state.game.level].levelType, entityTileSet);
            const animation = animateLoot(toward.subtract(item.pos), 0, itemTiles[item.type], delay > 0);
            state.particles.push({pos: item.pos, animation});
        },
        guardSlide(guard, posGuardOld, pulledGuard) {
            const gpos0 = vec2.clone(posGuardOld).subtract(guard.pos);
            const gpos1 = vec2.create();

            let tweenSeq;

            if (pulledGuard) {
                tweenSeq = [{pt0:gpos0, pt1:gpos1, duration:0.2, fn:tween.easeOutQuad}];
            } else {
                const gp = vec2.fromValues(0.5*(posGuardOld[0]-guard.pos[0]),0.5*(posGuardOld[1]-guard.pos[1]));
                tweenSeq = [
                    {pt0:gpos0, pt1:gp, duration:0.2, fn:tween.easeInQuad},
                    {pt0:gp, pt1:gpos1, duration:0.1, fn:tween.easeOutQuad},
                ];
            }

            state.visuals.guard(guard).animation = new SpriteAnimation(tweenSeq, []);
        },
        treasureGate(gate) {
            const animation = new FrameAnimator(entityTileSet.treasureGateAnimation, 0.3, 0, 1);
            animation.removeOnFinish = true;
            state.particles.push({pos: gate.pos, animation});
        },
        exitStep(posOld, posNew, dx, dy) {
            const start = vec2.create();
            const end = vec2.clone(posNew).subtract(posOld);
            let mid = start.add(end).scale(0.5).add(vec2.fromValues(0,0.0625));

            const tweenSeq = [
                {pt0:start, pt1:mid, duration:0.1, fn:tween.easeInQuad},
                {pt0:mid, pt1:end, duration:0.1, fn:tween.easeOutQuad},
                {pt0:end, pt1:end, duration:(dy>0)?0.5:0.1, fn:tween.easeOutQuad}
            ];

            const tile = dx<0? entityTileSet.playerTiles.left:
                         dx>0? entityTileSet.playerTiles.right:
                         dy>0? entityTileSet.playerTiles.up:
                         entityTileSet.playerTiles.down;
            state.visuals.player(state.game.player).animation = new SpriteAnimation(tweenSeq, [tile, tile, tile, tile]);
        },
        step(posOld, posNew, dx, dy, fromCrouch, crouch, pushingGuard, bounceBack) {
            const start = vec2.clone(posOld).subtract(posNew);
            const end = vec2.create();
            const mid = start.add(end).scale(0.5).add(vec2.fromValues(0,0.0625));

            let tweenSeq: Array<TweenData>;

            if (pushingGuard) {
                const gp = vec2.fromValues(0.5*(posOld[0]-posNew[0]),0.5*(posOld[1]-posNew[1]));
                tweenSeq = [
                    {pt0:start, pt1:gp, duration:0.2, fn:tween.easeInQuad},
                    {pt0:gp, pt1:end, duration:0.1, fn:tween.easeOutQuad},
                ];
            } else {
                const dtStep = bounceBack ? 0.05 : 0.1;
                tweenSeq = [
                    {pt0:start, pt1:mid, duration:dtStep, fn:tween.easeInQuad},
                    {pt0:mid, pt1:end, duration:dtStep, fn:tween.easeOutQuad},
                    {pt0:end, pt1:end, duration:(dy>0 && !crouch)?0.5:0.1, fn:tween.easeOutQuad}
                ]
                if(dy>0 && !crouch) tweenSeq.push({pt0:end, pt1:end, duration:0.1, fn:tween.easeOutQuad})
            }

            const baseTile =    dx<0? entityTileSet.playerTiles.left:
                                dx>0? entityTileSet.playerTiles.right:
                                dy>0? entityTileSet.playerTiles.up:
                                entityTileSet.playerTiles.down;
            const tile1 = fromCrouch? entityTileSet.playerTiles.hidden:baseTile;
            const tile2 = crouch? entityTileSet.playerTiles.hidden:baseTile;
            const tile3 = crouch? entityTileSet.playerTiles.hidden:entityTileSet.playerTiles.left;
            state.visuals.player(state.game.player).animation = new SpriteAnimation(tweenSeq, [tile1, tile2, tile2, tile3]);
        },
        exitLeap(posOld, posNew, dx, dy) {
            const start = vec2.create();
            const end = vec2.clone(posNew).subtract(posOld);
            let mid = start.add(end).scale(0.5).add(vec2.fromValues(0,0.25));
            const tile = dx<0? entityTileSet.playerTiles.left:
                         dx>0? entityTileSet.playerTiles.right:
                         dy>0? entityTileSet.playerTiles.up:
                         entityTileSet.playerTiles.down;

            const tweenSeq = [
                {pt0:start, pt1:mid, duration:0.1, fn:tween.easeInQuad},
                {pt0:mid, pt1:end, duration:0.1, fn:tween.easeOutQuad},
                {pt0:end, pt1:end, duration:(dy>0)?0.5:0.1, fn:tween.easeOutQuad}
            ]

            state.visuals.player(state.game.player).animation = new SpriteAnimation(tweenSeq, [tile, tile, tile]);
        },
        leap(posOld, landing, via, dx, dy, hid, attacking) {
            const start = posOld.subtract(landing);
            const end = vec2.create();
            const arc = attacking ? via.subtract(landing) : start.add(end);
            const mid = arc.scale(0.5).add(vec2.fromValues(0, 0.25));
            const tile = dx<0? entityTileSet.playerTiles.left:
                         dx>0? entityTileSet.playerTiles.right:
                         dy>0? entityTileSet.playerTiles.up:
                         entityTileSet.playerTiles.down;

            const tweenSeq = [
                {pt0:start, pt1:mid, duration:attacking ? 0.15 : 0.1, fn:tween.easeInQuad},
                {pt0:mid, pt1:end, duration:0.1, fn:tween.easeOutQuad},
                {pt0:end, pt1:end, duration:(dy>0 && !hid)?0.5:0.1, fn:tween.easeOutQuad}
            ]
            if(dy>0 && !hid) tweenSeq.push({pt0:end, pt1:end, duration:0.1, fn:tween.easeOutQuad})

            const tile2 = hid? entityTileSet.playerTiles.hidden : tile;
            state.visuals.player(state.game.player).animation = new SpriteAnimation(tweenSeq, [tile, tile2, tile2, entityTileSet.playerTiles.left]);
        },
        guardAdvance(guard, from, to) {
            state.visuals.guard(guard).animation = new SpriteAnimation([
                {pt0: from.subtract(to), pt1: vec2.create(), duration: 0.2, fn: tween.linear},
            ], []);
        },
        guardAttack(guard, playerPosition) {
            const start = vec2.create();
            const middle = playerPosition.subtract(guard.pos).scale(0.5);
            state.visuals.guard(guard).animation = new SpriteAnimation([
                {pt0: start, pt1: middle, duration: 0.1, fn: tween.easeInQuad},
                {pt0: middle, pt1: start, duration: 0.1, fn: tween.easeOutQuad},
            ], []);
        },
        clearGuardSpeech() { state.visuals.speaker = undefined; },
        guardSpeech(kind, speaker, volume, pan, above) {
            const sound = state.subtitledSounds[soundNameForGuardSpeech(kind)]?.play(volume, pan);
            state.popups.setSpeech(sound?.subtitle ?? '...', speaker, above);
            state.visuals.speaker = speaker;
        },
    };
}
