import type { PlayerCommand } from './commands';
import { directionOffsets,StepType } from './commands';
import { tryPlayerLeap,tryPlayerStep } from './movement';
import type { SimulationState } from './state';
import { tryPlayerWait } from './turn';

export type { Direction,PlayerCommand } from './commands';
export type { TurnFeedback } from './feedback';
export type { HeistState,SimulationState } from './state';

export function dispatchCommand(state: SimulationState, command: PlayerCommand) {
    if (command.type === 'wait') {
        tryPlayerWait(state);
    } else {
        const [dx, dy] = directionOffsets[command.direction];
        if (command.type === 'step') {
            tryPlayerStep(state, dx, dy, StepType.Normal);
        } else {
            tryPlayerLeap(state, dx, dy);
        }
    }
}
