import { vec2 } from '../my-matrix';
import type { Player } from '../world/game-map';
import { updateDir, type GuardData } from '../world/guard';
import { GuardMode } from '../world/guard-mode';
import { isRelaxedGuardMode } from '../world/guard-policy';
import { ladderArrivals, type FloorId, type Mansion, type Stair } from '../world/mansion';
import { clearVerticalSight } from '../world/vertical-sight';

type Trail = {target: FloorId; turns: number};

export class MansionPursuit {
    private readonly trails = new Map<GuardData, Trail>();
    private readonly posts = new Map<GuardData, {floor: FloorId; path: vec2[]}>();

    clear() {
        this.trails.clear();
        this.posts.clear();
    }

    followDeparture(mansion: Mansion, from: FloorId, to: FloorId) {
        const map = mansion.floors.find(floor => floor.id === from)?.map;
        if (!map) return;
        for (const guard of map.guards) {
            if (guard.mode === GuardMode.ChaseVisibleTarget) this.trails.set(guard, {target: to, turns: 12});
        }
    }

    advance(mansion: Mansion, active: FloorId, player: Player): {spottings: number; arrivals: number} {
        let spottings = 0, arrivals = 0;
        const current = mansion.floors.find(floor => floor.id === active)?.map;
        if (!current) return {spottings, arrivals};
        const hidden = player.hidden(current);
        const guards = mansion.floors.filter(floor => floor.id !== active)
            .flatMap(floor => floor.map.guards.map(guard => ({floor, guard})));
        const lit = current.cells.atVec(player.pos).lit > 0;
        for (const {floor, guard} of guards) {
            if (guard.mode === GuardMode.Unconscious) {
                this.trails.delete(guard);
                continue;
            }
            const {map, id} = floor;
            const dx = player.pos[0] - guard.pos[0], dy = player.pos[1] - guard.pos[1];
            const distance = dx * dx + dy * dy + (2 * (id - active)) ** 2;
            if (!hidden && distance < guard.sightCutoff(lit) &&
                (guard.mode === GuardMode.ChaseVisibleTarget || dx * guard.dir[0] + dy * guard.dir[1] >= 0) &&
                clearVerticalSight(mansion, id, guard.pos, active, player.pos, player.elevated)) {
                if (isRelaxedGuardMode(guard.mode)) spottings++;
                guard.mode = GuardMode.ChaseVisibleTarget;
                this.trails.set(guard, {target: active, turns: 12});
            }
            const trail = this.trails.get(guard);
            if (!trail || trail.turns-- <= 0 || trail.target === id) {
                if (trail) {
                    this.trails.delete(guard);
                    guard.mode = GuardMode.Patrol;
                }
                continue;
            }
            const ladder = towardFloor(mansion, id, trail.target);
            if (!ladder) continue;
            const approaches = ladderArrivals(map, ladder);
            if (!approaches.some(pos => pos.equals(guard.pos))) {
                const [x,y] = guard.pos;
                const rect = {
                    posMin: vec2.fromValues(Math.max(0,x - 1), Math.max(0,y - 1)),
                    posMax: vec2.fromValues(Math.min(map.cells.sizeX,x + 2), Math.min(map.cells.sizeY,y + 2)),
                };
                const distances = map.computeDistanceField(approaches.map(pos => ({priority: 0, pos})), rect);
                const next = map.nextPositions(distances, guard.pos).find(pos =>
                    !map.guards.some(other => other !== guard && other.pos.equals(pos)));
                if (next && !next.equals(guard.pos)) {
                    updateDir(guard.dir, guard.pos, next);
                    vec2.copy(guard.pos, next);
                    if (guard.hasTorch) map.computeLighting(null);
                }
                continue;
            }
            const target = mansion.floors.find(floor => floor.id === ladder.destination);
            const reciprocal = target?.map.stairs.find(candidate => candidate.destination === id);
            if (!target || !reciprocal) continue;
            const landing = ladderArrivals(target.map, reciprocal).find(pos =>
                !(target.id === active && player.pos.equals(pos)) &&
                !target.map.guards.some(other => other.pos.equals(pos)));
            if (!landing) continue;

            const post = this.posts.get(guard) ?? {floor: id, path: guard.patrolPath};
            this.posts.set(guard, post);
            map.guards.splice(map.guards.indexOf(guard), 1);
            target.map.guards.push(guard);
            vec2.copy(guard.pos, landing);
            vec2.copy(guard.goal, target.id === active ? player.pos : landing);
            guard.patrolPath = target.id === post.floor ? post.path : [vec2.clone(landing)];
            guard.patrolPathIndex = 0;
            guard.goals = [vec2.clone(landing)];
            map.computeLighting(null);
            target.map.computeLighting(target.id === active ? player : null);
            if (target.id === active) {
                arrivals++;
                this.trails.delete(guard);
                guard.mode = GuardMode.MoveToLastSighting;
                guard.modeTimeout = 6;
            }
        }
        return {spottings, arrivals};
    }
}

function towardFloor(mansion: Mansion, from: FloorId, to: FloorId): Stair | undefined {
    const frontier: {id: FloorId; first?: Stair}[] = [{id: from}];
    const visited = new Set<FloorId>([from]);
    for (const {id, first} of frontier) {
        if (id === to) return first;
        const floor = mansion.floors.find(floor => floor.id === id);
        for (const stair of floor?.map.stairs ?? []) {
            if (visited.has(stair.destination)) continue;
            visited.add(stair.destination);
            frontier.push({id: stair.destination, first: first ?? stair});
        }
    }
    return undefined;
}
