import { generatorVersion, rulesVersion } from '../../core/versions';
import { validateFinalMap } from '../../generation/validation';
import { fixupWalls } from '../../generation/world-building';
import { vec2 } from '../../my-matrix';
import type { LevelSpec } from '../../run/state';
import { canLeapToPos, canStepToPos, resolveElevatedMove } from '../../simulation/movement-rules';
import { CellGrid, GameMap, Player } from '../../world/game-map';
import { GuardData } from '../../world/guard';
import { assignLadderArrivals, FloorId, floorName, type Mansion, type MansionFloor } from '../../world/mansion';
import { cacheCellInfo } from '../../world/mutations';
import { ItemType, TerrainType, isDoorItemType, isGroundTerrainType, isHingedDoorTerrainType, isWallTerrainType } from '../../world/tiles';
import { windowAllowsDirection } from '../../world/traversal';
import { itemPalette, levelThemes, sameTile, terrainAt, terrainPalette, type LevelFile, type LevelFloor, type TilePosition } from './format';

const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]] as const;
const vector = ([x, y]: TilePosition) => vec2.fromValues(x, y);

export function buildCustomLevel(level: LevelFile): {mansion: Mansion; spec: LevelSpec} {
    const {floors} = level;
    const ground = floors.find(floor => floor.id === FloorId.First);
    if (!ground || floors.some(floor => floor.terrain.length !== ground.terrain.length ||
        floor.terrain[0].length !== ground.terrain[0].length)) {
        throw new Error('Every story needs the same grid dimensions.');
    }
    const linked = new Set<FloorId>([FloorId.First]);
    for (const floor of floors) {
        const targets = new Set<FloorId>();
        for (const stair of floor.stairs) {
            const destination = floors.find(other => other.id === stair.to);
            if (stair.to === floor.id || targets.has(stair.to) ||
                !destination?.stairs.some(other => other.to === floor.id)) {
                throw new Error(`${floorName(floor.id)} needs a unique pair of ladder tiles for each connected floor.`);
            }
            targets.add(stair.to);
        }
    }
    for (const id of linked) {
        for (const stair of floors.find(floor => floor.id === id)!.stairs) linked.add(stair.to);
    }
    if (linked.size !== floors.length) throw new Error('Connect every floor to the first floor using ladders.');
    if (!level.exits.length) throw new Error('Place an exit along the edge of the first floor.');

    const maps = floors.map(floor => ({id: floor.id, map: buildFloor(level, floor)}));
    validateRoutes(maps);
    const totalLoot = maps.reduce((sum, {map}) => sum +
        map.items.filter(item => item.type === ItemType.Coin).length +
        map.guards.filter(guard => guard.hasPurse).length, 0);
    return {
        mansion: {floors: maps},
        spec: {
            levelType: levelThemes[level.theme].type, difficulty: 1, numRoomsX: 1, numRoomsY: 1,
            totalLoot, seed: 'custom/' + level.title, rulesVersion, generatorVersion,
        },
    };
}

function buildFloor(level: LevelFile, floor: LevelFloor): GameMap {
    const label = floorName(floor.id);
    const {terrain} = floor;
    const cells = new CellGrid(terrain[0].length, terrain.length);
    const map = new GameMap(cells);
    map.hasElevation = true;
    for (let y = 0; y < cells.sizeY; y++) {
        for (let x = 0; x < cells.sizeX; x++) {
            const code = terrainAt(floor, [x, y]);
            const tile = terrainPalette[code];
            if (code === 'o') map.openings.add(cells.index(x,y));
            cells.at(x, y).type = tile.type;
            if ('fixture' in tile) map.items.push({type: tile.fixture, pos: vec2.fromValues(x, y)});
        }
    }

    const marked = new Set<number>();
    function reserve(at: TilePosition, purpose: string, item = false) {
        const index = cells.index(...at);
        const terrain = cells.values[index].type;
        if (marked.has(index)) throw new Error(`${label} has overlapping objects at ${at.join(', ')}.`);
        if (map.openings.has(index) || !isGroundTerrainType(terrain) || (terrain === TerrainType.GroundWater && !item)) {
            throw new Error(`${label} ${purpose} needs an open floor tile at ${at.join(', ')}.`);
        }
        marked.add(index);
    }
    const first = floor.id === FloorId.First;
    map.allowsEscape = first;
    if (first) {
        reserve(level.start, 'player start');
        map.exitPositions = level.exits.map(at => {
            if (at[0] !== 0 && at[1] !== 0 && at[0] !== cells.sizeX - 1 && at[1] !== cells.sizeY - 1) {
                throw new Error('Each exit must be on the edge of the first floor.');
            }
            reserve(at, 'exit');
            return vector(at);
        });
    }
    for (const stair of floor.stairs) {
        reserve(stair.at, 'ladder');
        map.stairs.push({pos: vector(stair.at), destination: stair.to});
    }
    for (const item of floor.items) {
        reserve(item.at, 'item', item.type === 'coin' || item.type === 'food');
        map.items.push({type: itemPalette[item.type].type, pos: vector(item.at)});
    }
    map.playerStartPos = vector(first ? level.start : floor.stairs[0].at);
    for (const at of floor.platforms ?? []) {
        if (!isGroundTerrainType(cells.at(...at).type) || map.stairs.some(stair => stair.pos.equals(vector(at)))) {
            throw new Error(`${label} ceiling platform needs a clear ceiling tile at ${at.join(', ')}.`);
        }
        map.platforms.add(cells.index(...at));
    }
    fixupWalls(cells);
    cacheCellInfo(map);
    for (const {patrol, torch, purse} of floor.guards) {
        reserve(patrol[0], 'guard start');
        const points = patrol.map(vector);
        for (let i = 0; i < points.length; i++) {
            const at = points[i];
            const prev = points[i - 1] ?? at;
            if (Math.max(Math.abs(at[0] - prev[0]), Math.abs(at[1] - prev[1])) > 1 ||
                !Number.isFinite(map.guardMoveCost(prev, at)) || (i > 0 && sameTile(patrol[i - 1], patrol[i]))) {
                throw new Error(`${label} guard patrol must follow neighboring clear tiles near ${patrol[i].join(', ')}.`);
            }
        }
        const guard = new GuardData(points.concat(points.slice(1, -1).reverse()), 0);
        guard.hasTorch = torch;
        guard.hasPurse = purse;
        map.guards.push(guard);
    }
    if (!assignLadderArrivals(map)) throw new Error(`${label} needs an open tile beside each ladder.`);
    validateFinalMap(map, {
        levelType: levelThemes[level.theme].type, difficulty: 1, numRoomsX: 1, numRoomsY: 1,
        totalLoot: floor.items.filter(item => item.type === 'coin').length + floor.guards.filter(guard => guard.purse).length,
        seed: level.title, rulesVersion, generatorVersion,
    });
    map.computeLighting(null);
    return map;
}

function validateRoutes(floors: MansionFloor[]) {
    const size = floors[0].map.cells.values.length;
    const floorIndices = new Map(floors.map((floor, index) => [floor.id, index]));
    const forward: number[][] = Array.from({length: size * 2 * floors.length}, () => []);
    const backward: number[][] = forward.map(() => []);
    const required: number[] = [];
    const key = (floor: MansionFloor, pos: vec2, elevated: boolean) =>
        2 * size * floorIndices.get(floor.id)! + Number(elevated) * size + floor.map.cells.indexVec(pos);
    function connect(from: number, to: number) {
        forward[from].push(to);
        backward[to].push(from);
    }

    for (const floor of floors) {
        const {map, id} = floor;
        const {cells} = map;
        const state = {gameMap: map, player: new Player(map.playerStartPos, false), finishedLevel: false};

        for (let i = 0; i < size; i++) {
            const x = i % cells.sizeX, y = Math.floor(i / cells.sizeX);
            const at = vec2.fromValues(x,y);
            const ground = key(floor, at, false);
            const high = key(floor, at, true);
            if (map.hasHighSurface(at)) {
                for (const [dx,dy] of directions) for (const leap of [false, true]) {
                    const move = resolveElevatedMove(state, at, true, dx, dy, leap, true);
                    if (move) connect(high, key(floor, move.to, move.elevated));
                }
            }
            if (!canStepToPos(state, at, true) && !canLeapToPos(state, at, true)) continue;
            required.push(ground);
            const ladder = map.stairAt(at);
            if (ladder) {
                const target = floors[floorIndices.get(ladder.destination)!];
                const arrival = target.map.stairs.find(stair => stair.destination === id)?.pos;
                if (arrival) connect(ground, key(target, arrival, false));
            }
            for (const [dx,dy] of directions) {
                const mid = vec2.fromValues(x + dx, y + dy);
                if (!cells.contains(mid[0], mid[1])) continue;
                if (canStepToPos(state, mid, true)) connect(ground, key(floor, mid, false));
                const climb = resolveElevatedMove(state, at, false, dx, dy, true, true);
                if (climb) {
                    connect(ground, key(floor, climb.to, true));
                    continue;
                }
                const end = vec2.fromValues(x + 2 * dx, y + 2 * dy);
                const middle = cells.atVec(mid);
                if (!cells.contains(end[0], end[1]) || cells.atVec(at).type === TerrainType.GroundWater ||
                    middle.blocksPlayerMove || !windowAllowsDirection(middle.type, dx, dy, cells.atVec(at).type) ||
                    (isHingedDoorTerrainType(middle.type) && map.items.some(item => item.pos.equals(mid) && isDoorItemType(item.type)))) continue;
                if (canLeapToPos(state, end, true)) connect(ground, key(floor, end, false));
            }
        }
    }

    const first = floors[floorIndices.get(FloorId.First)!];
    const origin = key(first, first.map.playerStartPos, false);
    const reachable = visit(forward, origin);
    const canReturn = visit(backward, origin);
    for (const index of required.concat([...reachable])) {
        if (reachable.has(index) && canReturn.has(index)) continue;
        const floor = floors[Math.floor(index / (2 * size))];
        const local = index % size;
        const width = floor.map.cells.sizeX;
        const label = floorName(floor.id);
        throw new Error(`${label} has no round trip to tile ${local % width}, ${Math.floor(local / width)}. Check ladders, openings, and ceiling platforms.`);
    }

    for (const floor of floors) {
        const start = 2 * size * floorIndices.get(floor.id)!;
        const visibleFrom = new Set<number>();
        for (const i of reachable) {
            if (i >= start && i < start + 2 * size) visibleFrom.add(i % size);
        }
        prepareExploration(floor.map, floorName(floor.id), visibleFrom);
    }
}

function prepareExploration(map: GameMap, label: string, reachable: Set<number>) {
    const {cells} = map;
    const interiorWalls = new Set<number>();
    for (let i = 0; i < cells.values.length; i++) {
        if (reachable.has(i) || map.openings.has(i)) continue;
        const x = i % cells.sizeX;
        const y = Math.floor(i / cells.sizeX);
        // The visibility rules can only reveal a blocked tile from an adjacent transparent tile.
        let canBeSeen = false;
        for (let dy = -1; dy <= 1; dy++) {
            for (let dx = -1; dx <= 1; dx++) {
                if ((dx || dy) && cells.contains(x + dx, y + dy) && !cells.at(x + dx, y + dy).blocksPlayerSight) {
                    canBeSeen = true;
                }
            }
        }
        if (canBeSeen) continue;
        if (!isWallTerrainType(cells.values[i].type)) throw new Error(`${label} has an enclosed fixture at ${x}, ${y}.`);
        interiorWalls.add(i);
        cells.values[i].seen = true;
    }

    // Start from unexplored viewpoints to cover large open areas in a few casts.
    const viewed = new Set<number>();
    for (const i of reachable) {
        if (cells.values[i].seen) continue;
        map.recomputeVisibility(vec2.fromValues(i % cells.sizeX, Math.floor(i / cells.sizeX)));
        viewed.add(i);
    }
    for (const i of reachable) {
        if (map.allSeen()) break;
        if (!viewed.has(i)) map.recomputeVisibility(vec2.fromValues(i % cells.sizeX, Math.floor(i / cells.sizeX)));
    }
    for (let i = 0; i < cells.values.length; i++) {
        const cell = cells.values[i];
        if (map.openings.has(i)) continue;
        if (!cell.seen && !isWallTerrainType(cell.type)) {
            throw new Error(`${label} contains a tile that cannot be explored. Open up the area around it.`);
        }
        const hiddenWall = interiorWalls.has(i) || !cell.seen;
        if (hiddenWall) map.numPreRevealedCells++;
        cell.seen = cell.identified = hiddenWall;
    }
}

function visit(edges: number[][], start: number): Set<number> {
    const seen = new Set([start]);
    for (const from of seen) for (const to of edges[from]) seen.add(to);
    return seen;
}
