export enum TerrainType {
    GroundNormal,
    GroundGrass,
    GroundWater,
    GroundMarble,
    GroundWood,
    GroundWoodCreaky,
    GroundVault,
    GroundTreasure,

    //  NSEW
    Wall0000,
    Wall0001,
    Wall0010,
    Wall0011,
    Wall0100,
    Wall0101,
    Wall0110,
    Wall0111,
    Wall1000,
    Wall1001,
    Wall1010,
    Wall1011,
    Wall1100,
    Wall1101,
    Wall1110,
    Wall1111,

    OneWayWindowE,
    OneWayWindowW,
    OneWayWindowN,
    OneWayWindowS,
    PortcullisNS,
    PortcullisEW,
    DoorNS,
    DoorEW,
    GardenDoorNS,
    GardenDoorEW,
    GroundRoof,
}

export enum ItemType {
    Chair,
    Table,
    BedL,
    BedR,
    DrawersShort,
    DrawersTall,
    Bookshelf,
    Shelf,
    Stove,
    Bush,
    Coin,
    Health,
    DoorNS,
    DoorEW,
    LockedDoorNS,
    LockedDoorEW,
    PortcullisNS,
    PortcullisEW,
    TorchUnlit,
    TorchLit,
    TorchCarry, //TODO: Next four don't belong here because they are carried by guards but solves a problem for now.
    PurseCarry,
    Key,
    KeyCarry,
    VaultTreasureBox,
    EmptyVaultTreasureBox,
    LootedVaultTreasureBox,
    Note,
    TreasureLock,
    TreasurePlinth,
    TreasureA,
    TreasureB,
    TreasureC,
    TreasureD,
    TreasureE,
}

export function isClimbableItem(type: ItemType): boolean {
    return type === ItemType.DrawersTall || type === ItemType.Bookshelf || type === ItemType.Shelf;
}

export function isPlinthTreasure(type: ItemType): boolean {
    return type === ItemType.TreasureA || type === ItemType.TreasureB ||
        type === ItemType.TreasureC || type === ItemType.TreasureD || type === ItemType.TreasureE;
}

export function isOverheadItem(type: ItemType): boolean {
    return type === ItemType.TreasureLock || isPlinthTreasure(type);
}

export function isGroundTerrainType(type: TerrainType): boolean {
    return (type >= TerrainType.GroundNormal && type <= TerrainType.GroundTreasure) || type === TerrainType.GroundRoof;
}

export function isWallTerrainType(type: TerrainType): boolean {
    // The sixteen wall tiles are indexed by their four connection bits.
    return type >= TerrainType.Wall0000 && type <= TerrainType.Wall1111;
}

export function isWindowTerrainType(type: TerrainType): boolean {
    return type === TerrainType.OneWayWindowE || type === TerrainType.OneWayWindowW ||
        type === TerrainType.OneWayWindowN || type === TerrainType.OneWayWindowS;
}

export function isGateTerrainType(type: TerrainType): boolean {
    return type === TerrainType.PortcullisNS || type === TerrainType.PortcullisEW;
}

export function isHingedDoorTerrainType(type: TerrainType): boolean {
    return type === TerrainType.DoorNS || type === TerrainType.DoorEW;
}

export function isDoorwayTerrainType(type: TerrainType): boolean {
    return isGateTerrainType(type) || isHingedDoorTerrainType(type) ||
        type === TerrainType.GardenDoorNS || type === TerrainType.GardenDoorEW;
}

export function connectsWallTile(type: TerrainType): boolean {
    return isWallTerrainType(type) || isWindowTerrainType(type) ||
        isGateTerrainType(type) || isHingedDoorTerrainType(type);
}

export function isLockedDoorItemType(type: ItemType): boolean {
    return type === ItemType.LockedDoorNS || type === ItemType.LockedDoorEW;
}

export function isHingedDoorItemType(type: ItemType): boolean {
    return type === ItemType.DoorNS || type === ItemType.DoorEW || isLockedDoorItemType(type);
}

export function isGateItemType(type: ItemType): boolean {
    return type === ItemType.PortcullisNS || type === ItemType.PortcullisEW;
}

export function isDoorItemType(type: ItemType): boolean {
    return isHingedDoorItemType(type) || isGateItemType(type);
}

export function isVaultBox(type: ItemType): boolean {
    return type === ItemType.VaultTreasureBox || type === ItemType.EmptyVaultTreasureBox ||
        type === ItemType.LootedVaultTreasureBox;
}

export function isTorchItemType(type: ItemType): boolean {
    return type === ItemType.TorchLit || type === ItemType.TorchUnlit;
}

export function blocksPlayerMovement(type: ItemType): boolean {
    return type === ItemType.DrawersTall || type === ItemType.Bookshelf ||
        type === ItemType.Shelf || type === ItemType.Stove || type === ItemType.TreasureLock;
}

export function blocksPlayerSight(type: ItemType): boolean {
    return isHingedDoorItemType(type);
}

export function blocksGuardSight(type: ItemType): boolean {
    return isDoorItemType(type) || type === ItemType.Bush || type === ItemType.DrawersTall ||
        type === ItemType.Bookshelf || type === ItemType.Shelf || type === ItemType.Stove;
}

export function hidesPlayer(type: ItemType): boolean {
    return type === ItemType.Table || type === ItemType.Bush || type === ItemType.BedL || type === ItemType.BedR;
}

export function canLeapOntoItemType(type: ItemType): boolean {
    return type !== ItemType.DrawersShort && type !== ItemType.TreasurePlinth &&
        type !== ItemType.TreasureLock && !isTorchItemType(type) && !isVaultBox(type) && !isPlinthTreasure(type);
}

export function blocksOrdinaryStep(type: ItemType): boolean {
    return !canLeapOntoItemType(type) || isGateItemType(type);
}
