export const rulesVersion = 2;
export const legacyGeneratorVersion = 1;
export const asymmetricGeneratorVersion = 2;
export const generatorVersion = 3;
export type GeneratorVersion = typeof legacyGeneratorVersion | typeof asymmetricGeneratorVersion | typeof generatorVersion;

export function isGeneratorVersion(version: number): version is GeneratorVersion {
    return version === legacyGeneratorVersion || version === asymmetricGeneratorVersion || version === generatorVersion;
}
