import { lastController } from '../controllers';
import type { InputScheme } from '../presentation/input-hints';
import type { State } from './state';
export function activeInputScheme(state: State): InputScheme {
    if (lastController === state.touchController && !state.touchController.mouseActive) return 'touch';
    if (Object.values(state.gamepadManager.gamepads).some(controller=>controller===lastController)) return 'gamepad';
    return 'keyboard';
}
